"use client";

import { toast } from 'sonner';
import { Suspense, useEffect, useState, useCallback, useRef } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import { devLogger } from '@/app/lib/logging/devLogger';
import type { ClassGroup, EditableSession } from '@/app/admin/classes-shared/types';
import {
  cloneTierFeeMap,
  HARD_CODED_TIER_FEES,
  type TierFeeMap,
} from '@/app/lib/teacherTierSchedule';
import { fetchTeacherTierFeeMap } from '@/app/lib/teacherTierFeesStore';
import { fetchTeacherLogCounts } from '@/app/admin/users/fetchTeacherLogCounts';
import { GROUP_ALIAS_RULES } from '../lib/groupAliases';
import ClassBundlePanelV2 from '../components/ClassBundlePanelV2';
import {
  getCleanClassTitle,
  getBundleTitleKey,
  makeBundleCompositeKey,
  getBundleTitleFromCompositeKey,
} from '../lib/v2BundleResolve';
import { buildGroupPlannedTotals } from '@/app/admin/classes-shared/lib/plannedRoundTotal';
import { SESSION_TYPE_OPTIONS } from '../lib/sessionTypeCategory';
import { resolveDefaultSessionPrice } from '../lib/bulkSessionDefaults';

const CREATE_TYPE_ICONS: Record<(typeof SESSION_TYPE_OPTIONS)[number]['value'], string> = {
  one_day_private: '🎓',
  regular_private: '🏠',
  regular_center: '🏢',
  one_day_center: '🎉',
  special_lecture: '⭐',
};

type DayOption = { label: string; value: number };
const DAYS: DayOption[] = [
  { label: '일', value: 0 },
  { label: '월', value: 1 },
  { label: '화', value: 2 },
  { label: '수', value: 3 },
  { label: '목', value: 4 },
  { label: '금', value: 5 },
  { label: '토', value: 6 },
];

type TimeStatus = 'upcoming' | 'ongoing' | 'completed';

type GroupView = ClassGroup & {
  timeStatus: TimeStatus;
  displayTeacherId: string | null;
  displayDateAt: string; // 리스트에 표시할 대표 날짜(보통 다음 수업일)
};

/** 같은 담당 + 정제 수업명(번들 키)인 행을 한 줄로 합쳐 표시 */
function mergeGroupViewsByBundleKey(rows: GroupView[]): GroupView[] {
  const byKey = new Map<string, GroupView[]>();
  for (const g of rows) {
    const k = makeBundleCompositeKey(g.displayTeacherId, g.title);
    if (!byKey.has(k)) byKey.set(k, []);
    byKey.get(k)!.push(g);
  }
  const out: GroupView[] = [];
  for (const [k, list] of byKey) {
    if (list.length === 1) {
      out.push(list[0]!);
      continue;
    }
    const sorted = [...list].sort(
      (a, b) => new Date(a.displayDateAt).getTime() - new Date(b.displayDateAt).getTime()
    );
    const first = sorted[0]!;
    const titleCanon = getBundleTitleFromCompositeKey(k) || getBundleTitleKey(first.title) || first.title;
    const teacherSet = new Set<string>();
    let minFirst = first.firstClassAt;
    let maxLast = first.lastClassAt;
    let minDisp = first.displayDateAt;
    let roundSum = 0;
    let completedSum = 0;
    for (const x of sorted) {
      roundSum += x.roundTotal;
      completedSum += x.completedCount;
      for (const tid of x.teacherIds) {
        if (tid) teacherSet.add(tid);
      }
      if (new Date(x.firstClassAt).getTime() < new Date(minFirst).getTime()) minFirst = x.firstClassAt;
      if (new Date(x.lastClassAt).getTime() > new Date(maxLast).getTime()) maxLast = x.lastClassAt;
      if (new Date(x.displayDateAt).getTime() < new Date(minDisp).getTime()) minDisp = x.displayDateAt;
    }
    const anyOngoing = sorted.some((x) => x.timeStatus === 'ongoing');
    out.push({
      ...first,
      groupId: first.groupId,
      title: titleCanon,
      roundTotal: roundSum,
      completedCount: completedSum,
      firstClassAt: minFirst,
      lastClassAt: maxLast,
      teacherIds: Array.from(teacherSet),
      displayDateAt: minDisp,
      displayTeacherId: first.displayTeacherId,
      timeStatus: anyOngoing ? 'ongoing' : 'upcoming',
    });
  }
  return out.sort((a, b) =>
    getCleanClassTitle(a.title).localeCompare(getCleanClassTitle(b.title), 'ko-KR')
  );
}

type BundleSelection = {
  bundleTitle: string;
  groupIds: string[];
};

type TeacherOption = {
  id: string;
  name: string;
  session_count?: number | null;
  logCount?: number | null;
  fee_private?: number | null;
  fee_group?: number | null;
  fee_center_main?: number | null;
  fee_center_assist?: number | null;
};

function ClassListPageV2Content() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const focusAppliedRef = useRef(false);
  const [supabase] = useState(() =>
    typeof window !== 'undefined' ? getSupabaseBrowserClient() : null
  );
  const [groups, setGroups] = useState<GroupView[]>([]);
  const [teacherMap, setTeacherMap] = useState<Record<string, string>>({});
  const [teachers, setTeachers] = useState<TeacherOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [tierFeeMap, setTierFeeMap] = useState<TierFeeMap>(() => cloneTierFeeMap(HARD_CODED_TIER_FEES));
  const [selectedBundle, setSelectedBundle] = useState<BundleSelection | null>(null);
  const [aliasGroupIdsByTitle, setAliasGroupIdsByTitle] = useState<Record<string, string[]>>({});
  const [bundleGroupIdsByKey, setBundleGroupIdsByKey] = useState<Record<string, string[]>>({});

  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [createStep, setCreateStep] = useState<1 | 2>(1);
  const [createLoading, setCreateLoading] = useState(false);
  const [createForm, setCreateForm] = useState({
    title: '',
    type: 'regular_private' as (typeof SESSION_TYPE_OPTIONS)[number]['value'],
    teacherId: '',
    startDate: new Date().toISOString().split('T')[0],
    startTime: '10:00',
    durationMinutes: '60',
    price: 30000,
    weeklyFrequency: 1,
    daysOfWeek: [new Date().getDay()],
    sessionCount: 4,
    roundWeight: 1,
  });
  const [editableSessions, setEditableSessions] = useState<EditableSession[]>([]);

  const resolveDefaultPrice = useCallback(
    (teacherId: string, clsType: string): number => {
      const selectedTeacher = teachers.find((t) => t.id === teacherId);
      return resolveDefaultSessionPrice(selectedTeacher, clsType, tierFeeMap);
    },
    [teachers, tierFeeMap],
  );

  const fetchGroups = useCallback(async () => {
    if (!supabase) return;
    try {
      const [sessionsRes, usersRes] = await Promise.all([
        supabase
          .from('sessions')
          .select('group_id, title, start_at, end_at, status, created_by, round_total, round_index')
          .not('status', 'in', '("deleted")'),
        supabase
          .from('users')
          .select('id, name, session_count, fee_private, fee_group, fee_center_main, fee_center_assist')
          .eq('is_active', true)
          .order('name', { ascending: true }),
      ]);

      if (usersRes.data) {
        const map: Record<string, string> = {};
        const base = usersRes.data as TeacherOption[];
        const logCountByTeacher = await fetchTeacherLogCounts(
          supabase,
          base.map((u) => u.id),
        );
        const list = base.map((u) => ({
          ...u,
          logCount: logCountByTeacher[u.id] ?? 0,
        }));
        list.forEach((u) => {
          map[u.id] = u.name ?? '';
        });
        setTeacherMap(map);
        setTeachers(list);
      }
      const { map: nextTierFeeMap } = await fetchTeacherTierFeeMap(supabase);
      setTierFeeMap(nextTierFeeMap);

      const { data, error } = sessionsRes;
      if (error) throw error;
      if (!data) {
        setGroups([]);
        return;
      }

      const plannedByGroup = buildGroupPlannedTotals(data as any[]);

      // ✅ 사이클 토글용 번들 키: 담당(created_by) + 정제 수업명이 같으면 같은 번들(별도 개설 포함)
      // (리스트에는 완료를 숨기지만, 모달에서는 토글로 볼 수 있어야 함)
      const bundleMap = new Map<string, Set<string>>();
      for (const row of data as any[]) {
        if (!row.group_id) continue;
        const titlePart = getBundleTitleKey(String(row.title || ''));
        if (!titlePart) continue;
        const key = makeBundleCompositeKey(
          row.created_by as string | null | undefined,
          String(row.title || '')
        );
        if (!bundleMap.has(key)) bundleMap.set(key, new Set<string>());
        bundleMap.get(key)!.add(String(row.group_id));
      }
      const nextBundle: Record<string, string[]> = {};
      for (const [k, set] of bundleMap.entries()) nextBundle[k] = Array.from(set);
      setBundleGroupIdsByKey(nextBundle);

      const now = Date.now();
      const byGroup = new Map<
        string,
        {
          g: GroupView;
          minStartMs: number;
          earliestUpcomingStartMs: number;
          earliestUpcomingTeacherId: string | null;
          earliestOngoingStartMs: number;
          ongoingTeacherId: string | null;
          maxEndMs: number;
          earliestUpcomingStartAt: string | null;
          earliestOngoingStartAt: string | null;
        }
      >();

      (data as any[]).forEach((row) => {
        if (!row.group_id) return;
        const key = row.group_id as string;
        const startAt = row.start_at as string;
        const endAt = row.end_at as string;
        const startMs = new Date(startAt).getTime();
        const endMs = new Date(endAt).getTime();
        const teacherId = (row.created_by as string | null) ?? null;
        const isOngoing = Number.isFinite(startMs) && Number.isFinite(endMs) && startMs <= now && now <= endMs;
        const isUpcoming = Number.isFinite(startMs) && startMs > now;

        const existing = byGroup.get(key);
        if (!existing) {
          const roundTotal = plannedByGroup[key] ?? Number(row.round_total) ?? 1;
          const g: GroupView = {
            groupId: key,
            title: row.title || '',
            roundTotal,
            completedCount: 0,
            firstClassAt: startAt,
            lastClassAt: endAt,
            teacherIds: teacherId ? [teacherId] : [],
            timeStatus: 'upcoming',
            displayTeacherId: teacherId,
            displayDateAt: startAt,
          };
          byGroup.set(key, {
            g,
            minStartMs: Number.isFinite(startMs) ? startMs : Number.POSITIVE_INFINITY,
            earliestUpcomingStartMs: isUpcoming ? startMs : Number.POSITIVE_INFINITY,
            earliestUpcomingTeacherId: isUpcoming ? teacherId : null,
            earliestOngoingStartMs: isOngoing ? startMs : Number.POSITIVE_INFINITY,
            ongoingTeacherId: isOngoing ? teacherId : null,
            maxEndMs: Number.isFinite(endMs) ? endMs : Number.NEGATIVE_INFINITY,
            earliestUpcomingStartAt: isUpcoming ? startAt : null,
            earliestOngoingStartAt: isOngoing ? startAt : null,
          });
        } else {
          const g = existing.g;
          g.roundTotal = plannedByGroup[key] ?? g.roundTotal;
          if (startAt < g.firstClassAt) g.firstClassAt = startAt;
          if (endAt > g.lastClassAt) g.lastClassAt = endAt;
          if (teacherId && !g.teacherIds.includes(teacherId)) g.teacherIds.push(teacherId);

          if (Number.isFinite(startMs)) existing.minStartMs = Math.min(existing.minStartMs, startMs);
          if (Number.isFinite(endMs)) existing.maxEndMs = Math.max(existing.maxEndMs, endMs);

          if (isOngoing && startMs < existing.earliestOngoingStartMs) {
            existing.earliestOngoingStartMs = startMs;
            existing.ongoingTeacherId = teacherId;
            existing.earliestOngoingStartAt = startAt;
          }
          if (isUpcoming && startMs < existing.earliestUpcomingStartMs) {
            existing.earliestUpcomingStartMs = startMs;
            existing.earliestUpcomingTeacherId = teacherId;
            existing.earliestUpcomingStartAt = startAt;
          }
        }
      });

      const list: GroupView[] = [];
      for (const {
        g,
        ongoingTeacherId,
        earliestUpcomingTeacherId,
        earliestOngoingStartMs,
        earliestUpcomingStartMs,
        maxEndMs,
        minStartMs,
        earliestUpcomingStartAt,
        earliestOngoingStartAt,
      } of byGroup.values()) {
        const hasOngoing = Number.isFinite(earliestOngoingStartMs) && earliestOngoingStartMs !== Number.POSITIVE_INFINITY;

        // ✅ 시리즈 관점: (1) 아직 시작 전이면 예정, (2) 모두 끝났으면 완료, (3) 그 외는 진행중
        const timeStatus: TimeStatus =
          Number.isFinite(minStartMs) && now < minStartMs
            ? 'upcoming'
            : Number.isFinite(maxEndMs) && now > maxEndMs
              ? 'completed'
              : 'ongoing';
        g.timeStatus = timeStatus;
        g.displayTeacherId = (hasOngoing ? ongoingTeacherId : earliestUpcomingTeacherId) ?? null;
        // ✅ 대표 날짜: 진행중이면 "가장 가까운 진행중(또는 다음 예정)", 예정이면 "다음 예정"
        g.displayDateAt =
          (timeStatus === 'ongoing' ? (earliestOngoingStartAt || earliestUpcomingStartAt) : earliestUpcomingStartAt) ||
          g.firstClassAt;
        if (timeStatus === 'completed') continue; // ✅ 완료(종료) 그룹은 목록에서 숨김
        list.push(g);
      }

      // ✅ 수업명(정제 후) 가나다순
      list.sort((a, b) => getCleanClassTitle(a.title).localeCompare(getCleanClassTitle(b.title), 'ko-KR'));

      // ✅ V2 가상 그룹(별칭): group_id 기반으로만 묶기(오탐 방지)
      const normalizeForAlias = (rawTitle: string) => {
        // (강사명) 같은 괄호 내용은 제거하고, 공백을 정리한 뒤 비교
        return getCleanClassTitle(rawTitle).replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
      };

      const getAliasTitleForGroup = (rawTitle: string): string | null => {
        const t = normalizeForAlias(rawTitle);
        for (const rule of GROUP_ALIAS_RULES) {
          const ok = rule.matchAny.some((m) => m.titleIncludesAll.every((needle) => t.includes(needle)));
          if (ok) return rule.aliasTitle;
        }
        return null;
      };

      const mergedByAlias = new Map<
        string,
        { row: GroupView; groupIds: string[] }
      >();
      const passthrough: GroupView[] = [];

      for (const g of list) {
        const alias = getAliasTitleForGroup(g.title);
        if (!alias) {
          passthrough.push(g);
          continue;
        }
        const existing = mergedByAlias.get(alias);
        if (!existing) {
          mergedByAlias.set(alias, { row: { ...g, title: alias }, groupIds: [g.groupId] });
        } else {
          existing.groupIds.push(g.groupId);
          // 대표 날짜는 더 빠른 값
          if (new Date(g.displayDateAt).getTime() < new Date(existing.row.displayDateAt).getTime()) {
            existing.row.displayDateAt = g.displayDateAt;
            existing.row.displayTeacherId = g.displayTeacherId;
            existing.row.timeStatus = g.timeStatus;
          }
          existing.row.roundTotal += g.roundTotal;
        }
      }

      const merged = Array.from(mergedByAlias.values()).map((x) => x.row);
      const combined = [...passthrough, ...merged].sort((a, b) =>
        getCleanClassTitle(a.title).localeCompare(getCleanClassTitle(b.title), 'ko-KR')
      );

      const displayRows = mergeGroupViewsByBundleKey(combined);

      const nextAliasMap: Record<string, string[]> = {};
      for (const [aliasTitle, v] of mergedByAlias.entries()) {
        nextAliasMap[aliasTitle] = v.groupIds;
      }
      setAliasGroupIdsByTitle(nextAliasMap);

      setGroups(displayRows);
    } catch (err) {
      const msg =
        err instanceof Error
          ? err.message
          : err && typeof err === 'object' && 'message' in err
            ? String((err as { message?: unknown }).message)
            : String(err);
      devLogger.error('[classes-v2 list] fetchGroups failed:', msg, err);
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  useEffect(() => {
    fetchGroups();
  }, [fetchGroups]);

  useEffect(() => {
    if (focusAppliedRef.current || loading) return;
    if (typeof window === 'undefined') return;
    const params = new URLSearchParams(window.location.search);
    const focusGroupId = params.get('focusGroupId');
    if (!focusGroupId) {
      focusAppliedRef.current = true;
      return;
    }
    let handled = false;
    for (const [aliasTitle, ids] of Object.entries(aliasGroupIdsByTitle)) {
      if (ids.includes(focusGroupId)) {
        setSelectedBundle({ bundleTitle: aliasTitle, groupIds: ids });
        handled = true;
        break;
      }
    }
    if (!handled) {
      for (const [key, ids] of Object.entries(bundleGroupIdsByKey)) {
        if (ids.includes(focusGroupId)) {
          setSelectedBundle({
            bundleTitle: getBundleTitleFromCompositeKey(key),
            groupIds: ids,
          });
          handled = true;
          break;
        }
      }
    }
    focusAppliedRef.current = true;
    router.replace('/admin/classes-v2/list', { scroll: false });
  }, [loading, aliasGroupIdsByTitle, bundleGroupIdsByKey, router]);

  const handleCreateChange = (field: string, value: string | number | boolean) => {
    setCreateForm((prev) => {
      const applyTierDefaultPrice = (next: typeof prev) =>
        next.teacherId
          ? {
              ...next,
              price: resolveDefaultPrice(next.teacherId, next.type),
            }
          : next;

      if (field === 'price') {
        return { ...prev, price: Number(value) || 0 };
      }

      if (field === 'type') {
        const v = String(value);
        const wasSingle =
          prev.type === 'one_day_private' || prev.type === 'one_day_center';
        const nextSingle = v === 'one_day_private' || v === 'one_day_center';
        if (nextSingle) {
          return applyTierDefaultPrice({
            ...prev,
            type: v as typeof prev.type,
            weeklyFrequency: 1,
            sessionCount: 1,
            roundWeight: 1,
            daysOfWeek: [new Date(`${prev.startDate}T${prev.startTime}`).getDay()],
          });
        }
        return applyTierDefaultPrice({
          ...prev,
          type: v as typeof prev.type,
          sessionCount: wasSingle ? 4 : prev.sessionCount,
        });
      }
      if (field === 'startDate') {
        const newBaseDay = new Date(`${value}T${prev.startTime}`).getDay();
        const oldBaseDay = new Date(`${prev.startDate}T${prev.startTime}`).getDay();
        const extras = prev.daysOfWeek.filter((d) => d !== oldBaseDay);
        const nextDays = [newBaseDay, ...extras.filter((d) => d !== newBaseDay)].sort(
          (a, b) => a - b
        );
        return { ...prev, startDate: String(value), daysOfWeek: nextDays };
      }
      if (field === 'weeklyFrequency') {
        const baseDay = new Date(`${prev.startDate}T${prev.startTime}`).getDay();
        const extras = prev.daysOfWeek.filter((d) => d !== baseDay);
        const needed = Number(value) - 1;
        const nextDays = [baseDay, ...extras.slice(0, needed)].sort((a, b) => a - b);
        return { ...prev, weeklyFrequency: Number(value), daysOfWeek: nextDays };
      }

      const next = { ...prev, [field]: value } as typeof prev;
      if (field === 'teacherId') {
        return applyTierDefaultPrice(next);
      }
      return next;
    });
  };

  useEffect(() => {
    if (searchParams.get('create') !== '1') return;
    setIsCreateOpen(true);
    setCreateStep(1);
    setEditableSessions([]);
    router.replace('/admin/classes-v2/list', { scroll: false });
  }, [router, searchParams]);

  const toggleCreateDay = (dayValue: number) => {
    setCreateForm((prev) => {
      const baseDay = new Date(`${prev.startDate}T${prev.startTime}`).getDay();
      if (dayValue === baseDay) return prev;
      const exists = prev.daysOfWeek.includes(dayValue);
      const nextDays = exists
        ? prev.daysOfWeek.filter((d) => d !== dayValue)
        : [...prev.daysOfWeek, dayValue].sort((a, b) => a - b);
      return { ...prev, daysOfWeek: nextDays };
    });
  };

  const buildCreateDates = () => {
    const sessions: Date[] = [];
    const start = new Date(`${createForm.startDate}T${createForm.startTime}`);
    if (createForm.type === 'one_day_private' || createForm.type === 'one_day_center') return [start];
    const selectedDays = createForm.daysOfWeek.length ? createForm.daysOfWeek : [start.getDay()];
    const cursor = new Date(start);

    while (sessions.length < createForm.sessionCount) {
      const weekStart = new Date(cursor);
      weekStart.setDate(cursor.getDate() - cursor.getDay());

      for (const d of selectedDays) {
        const dayDate = new Date(weekStart);
        dayDate.setDate(weekStart.getDate() + d);
        dayDate.setHours(start.getHours(), start.getMinutes(), 0, 0);

        if (dayDate >= start && sessions.length < createForm.sessionCount) {
          sessions.push(new Date(dayDate));
        }
      }
      cursor.setDate(cursor.getDate() + 7);
    }
    return sessions;
  };

  const initializeEditableSessions = () => {
    const dates = buildCreateDates();
    const next: EditableSession[] = dates.map((startDateTime, index) => {
      const endDateTime = new Date(startDateTime);
      endDateTime.setMinutes(
        endDateTime.getMinutes() + Number(createForm.durationMinutes || '60')
      );
      return {
        roundIndex: index + 1,
        startAt: startDateTime,
        endAt: endDateTime,
        teacherId: createForm.teacherId,
        price: Number(createForm.price) || 0,
      };
    });
    setEditableSessions(next);
  };

  const goToCreateStep2 = () => {
    if (!createForm.title || !createForm.teacherId) return toast.error('수업명과 강사를 확인해주세요!');
    if (
      createForm.type !== 'one_day_private' &&
      createForm.type !== 'one_day_center' &&
      createForm.weeklyFrequency > 1 &&
      createForm.daysOfWeek.length < createForm.weeklyFrequency
    ) {
      return toast.error('주간 횟수만큼 요일을 선택해주세요.');
    }
    initializeEditableSessions();
    setCreateStep(2);
  };

  const applyFirstRowToAll = () => {
    if (!editableSessions.length) return;
    const first = editableSessions[0];
    const updated = editableSessions.map((s, idx) => {
      if (idx === 0) return s;
      const start = new Date(s.startAt);
      start.setHours(first.startAt.getHours(), first.startAt.getMinutes(), 0, 0);
      const end = new Date(start);
      const diffMinutes = (first.endAt.getTime() - first.startAt.getTime()) / (1000 * 60);
      end.setMinutes(end.getMinutes() + diffMinutes);
      return { ...s, teacherId: first.teacherId, price: first.price, startAt: start, endAt: end };
    });
    setEditableSessions(updated);
  };

  const resetCreate = () => {
    setCreateStep(1);
    setEditableSessions([]);
    setCreateForm({
      title: '',
      type: 'regular_private',
      teacherId: '',
      startDate: new Date().toISOString().split('T')[0],
      startTime: '10:00',
      durationMinutes: '60',
      price: 30000,
      weeklyFrequency: 1,
      daysOfWeek: [new Date().getDay()],
      sessionCount: 4,
      roundWeight: 1,
    });
  };

  const handleCreateSubmit = async () => {
    if (!supabase) return;
    if (!editableSessions.length) return toast.error('회차가 없습니다. 회차를 먼저 생성해주세요.');

    setCreateLoading(true);
    try {
      const commonGroupId = crypto.randomUUID();
      const sorted = [...editableSessions].sort((a, b) => a.roundIndex - b.roundIndex);
      const totalRounds = sorted.length;

      const isSingleSessionType =
        createForm.type === 'one_day_private' || createForm.type === 'one_day_center';
      const sessionType = createForm.type;

      const sessionsToInsert: Record<string, unknown>[] = [];
      sorted.forEach((session, idx) => {
        const roundIndex = idx + 1;
        const roundDisplay = isSingleSessionType
          ? '1/1'
          : `${roundIndex}/${totalRounds}`;

        sessionsToInsert.push({
          title: createForm.title,
          session_type: sessionType,
          start_at: session.startAt.toISOString(),
          end_at: session.endAt.toISOString(),
          status: 'opened',
          group_id: commonGroupId,
          sequence_number: roundIndex,
          round_index: roundIndex,
          round_total: totalRounds,
          round_display: roundDisplay,
          price: Number(session.price) || 0,
          created_by: session.teacherId || createForm.teacherId,
        });
      });

      const { error } = await supabase.from('sessions').insert(sessionsToInsert);
      if (error) throw error;

      toast.success('수업이 성공적으로 등록되었습니다!');
      setIsCreateOpen(false);
      resetCreate();
      fetchGroups();
    } catch (err: unknown) {
      devLogger.error(err);
      toast.error('등록 중 에러가 발생했습니다.');
    } finally {
      setCreateLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50">
      <main className="flex-1 min-w-0 px-3 sm:px-6 py-4 sm:py-6 overflow-auto">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between mb-6">
          <div className="min-w-0">
            <h1 className="text-xl sm:text-2xl font-black text-slate-900">수업 목록 (V2)</h1>
            <p className="text-xs text-slate-500 font-bold mt-1">
              group_id 기준으로 묶인 수업 시리즈입니다.
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-2 shrink-0">
            <button
              type="button"
              onClick={() => setIsCreateOpen(true)}
              className="px-4 py-2 rounded-full text-sm font-bold bg-blue-600 text-white hover:bg-blue-700"
            >
              새 수업 개설
            </button>
            <Link
              href="/admin/classes-v2/calendar"
              className="px-4 py-2 rounded-full text-sm font-bold bg-white border border-slate-200 text-slate-700 hover:bg-slate-100"
            >
              캘린더 보기 (V2)
            </Link>
          </div>
        </div>

        {isCreateOpen && (
          <div className="fixed inset-0 z-[400]">
            <div className="absolute inset-0 bg-black/40" onClick={() => setIsCreateOpen(false)} />
            <div className="absolute inset-0 flex items-center justify-center p-3 sm:p-4">
              <div className="w-full max-w-4xl max-h-[calc(100dvh-2rem)] flex flex-col bg-white rounded-2xl sm:rounded-3xl shadow-2xl border border-slate-100 overflow-hidden">
                <div className="px-4 sm:px-6 py-3 sm:py-4 border-b border-slate-100 flex items-center justify-between gap-2 shrink-0">
                  <div>
                    <h2 className="text-lg font-black text-slate-900">수업 개설 (V2)</h2>
                    <p className="text-xs text-slate-500 font-bold mt-1">
                      기존 개설 로직(날짜 생성 → 회차 편집 → insert)을 그대로 사용합니다.
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => {
                      setIsCreateOpen(false);
                      resetCreate();
                    }}
                    className="px-3 py-1.5 rounded-full text-xs font-black bg-slate-100 text-slate-700 hover:bg-slate-200"
                  >
                    닫기
                  </button>
                </div>

                <div className="p-4 sm:p-6 space-y-6 overflow-y-auto min-h-0">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {SESSION_TYPE_OPTIONS.map((t) => (
                      <button
                        key={t.value}
                        type="button"
                        onClick={() => handleCreateChange('type', t.value)}
                        className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-1 transition-all ${
                          createForm.type === t.value
                            ? 'border-blue-600 bg-blue-50 text-blue-700'
                            : 'border-slate-100 bg-white text-slate-400 hover:text-slate-600'
                        }`}
                      >
                        <span className="text-2xl">{CREATE_TYPE_ICONS[t.value]}</span>
                        <span className="text-sm font-black text-center leading-tight">{t.label}</span>
                      </button>
                    ))}
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">수업명</label>
                      <input
                        type="text"
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold"
                        value={createForm.title}
                        onChange={(e) => handleCreateChange('title', e.target.value)}
                        placeholder="예: 스피치 8회"
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">담당 강사</label>
                      <select
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold"
                        value={createForm.teacherId}
                        onChange={(e) => handleCreateChange('teacherId', e.target.value)}
                      >
                        <option value="">강사를 선택하세요</option>
                        {teachers.map((t) => (
                          <option key={t.id} value={t.id}>
                            {t.name} T
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">첫 수업일</label>
                      <input
                        type="date"
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-sm font-bold"
                        value={createForm.startDate}
                        onChange={(e) => handleCreateChange('startDate', e.target.value)}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">시작 시간</label>
                      <input
                        type="time"
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-sm font-bold"
                        value={createForm.startTime}
                        onChange={(e) => handleCreateChange('startTime', e.target.value)}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">수업 시간</label>
                      <select
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-sm font-bold"
                        value={createForm.durationMinutes}
                        onChange={(e) => handleCreateChange('durationMinutes', e.target.value)}
                      >
                        {[60, 90, 120].map((m) => (
                          <option key={m} value={m}>
                            {m}분
                          </option>
                        ))}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-black text-slate-600">수업료(1회)</label>
                      <input
                        type="number"
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-sm font-bold"
                        value={createForm.price}
                        onChange={(e) => handleCreateChange('price', Number(e.target.value))}
                      />
                    </div>
                  </div>

                  {createForm.type !== 'one_day_private' &&
                    createForm.type !== 'one_day_center' && (
                    <div className="bg-slate-50 border border-slate-200 rounded-2xl p-4 space-y-3">
                      <div className="flex items-center gap-3 flex-wrap">
                        <label className="text-xs font-black text-slate-700">주당 횟수</label>
                        <select
                          value={createForm.weeklyFrequency}
                          onChange={(e) => handleCreateChange('weeklyFrequency', Number(e.target.value))}
                          className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-xs font-bold"
                        >
                          {[1, 2].map((n) => (
                            <option key={n} value={n}>
                              {n}회
                            </option>
                          ))}
                        </select>

                        <label className="text-xs font-black text-slate-700">총 회차</label>
                        <input
                          type="number"
                          className="w-20 bg-white border border-slate-200 rounded-lg px-2 py-2 text-xs font-bold"
                          value={createForm.sessionCount}
                          onChange={(e) => handleCreateChange('sessionCount', Number(e.target.value))}
                        />

                        <label className="text-xs font-black text-slate-700">회차 표시</label>
                        <select
                          value={createForm.roundWeight}
                          onChange={(e) => handleCreateChange('roundWeight', Number(e.target.value))}
                          className="bg-white border border-slate-200 rounded-lg px-3 py-2 text-xs font-bold"
                        >
                          <option value={1}>기본</option>
                          <option value={1.5}>90분(1.5회)</option>
                        </select>
                      </div>

                      {createForm.weeklyFrequency === 1 ? (
                        <div className="text-xs font-bold text-slate-600">
                          수업 요일:{" "}
                          {
                            DAYS.find(
                              (d) =>
                                d.value ===
                                new Date(`${createForm.startDate}T${createForm.startTime}`).getDay()
                            )?.label
                          }
                          요일 (첫 수업일 기준 자동)
                        </div>
                      ) : (
                        <div className="space-y-2">
                          <div className="text-xs font-black text-slate-700">
                            추가 요일 선택 ({createForm.weeklyFrequency - 1}개 더)
                          </div>
                          <div className="flex gap-2">
                            {DAYS.map((d) => {
                              const baseDay = new Date(
                                `${createForm.startDate}T${createForm.startTime}`
                              ).getDay();
                              const isBase = d.value === baseDay;
                              const isSelected = createForm.daysOfWeek.includes(d.value);
                              return (
                                <button
                                  key={d.value}
                                  type="button"
                                  onClick={() => toggleCreateDay(d.value)}
                                  disabled={isBase}
                                  className={`flex-1 py-2 rounded-lg text-xs font-black transition-all ${
                                    isBase
                                      ? 'bg-blue-600 text-white cursor-not-allowed'
                                      : isSelected
                                        ? 'bg-slate-900 text-white'
                                        : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                                  }`}
                                >
                                  {d.label}
                                </button>
                              );
                            })}
                          </div>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span
                        className={`inline-flex px-3 py-1 rounded-full text-xs font-black ${
                          createStep === 1 ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-600'
                        }`}
                      >
                        1) 기본 설정
                      </span>
                      <span
                        className={`inline-flex px-3 py-1 rounded-full text-xs font-black ${
                          createStep === 2 ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-600'
                        }`}
                      >
                        2) 회차 편집
                      </span>
                    </div>
                    {createStep === 1 ? (
                      <button
                        type="button"
                        onClick={goToCreateStep2}
                        disabled={createLoading}
                        className="px-4 py-2 rounded-full text-sm font-black bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50 shrink-0"
                      >
                        회차 설정으로
                      </button>
                    ) : (
                      <div className="flex flex-wrap gap-2 justify-end">
                        <button
                          type="button"
                          onClick={() => setCreateStep(1)}
                          className="px-4 py-2 rounded-full text-sm font-black bg-slate-100 text-slate-700 hover:bg-slate-200"
                        >
                          기본 설정 수정
                        </button>
                        <button
                          type="button"
                          onClick={applyFirstRowToAll}
                          className="px-4 py-2 rounded-full text-sm font-black bg-slate-100 text-slate-700 hover:bg-slate-200"
                          disabled={!editableSessions.length}
                        >
                          전체 동일 적용
                        </button>
                        <button
                          type="button"
                          onClick={handleCreateSubmit}
                          disabled={createLoading}
                          className="px-4 py-2 rounded-full text-sm font-black bg-emerald-600 text-white hover:bg-emerald-700 disabled:opacity-50"
                        >
                          {createLoading ? '등록 중...' : '등록'}
                        </button>
                      </div>
                    )}
                  </div>

                  {createStep === 2 && (
                    <div className="overflow-x-auto rounded-2xl border border-slate-100">
                      <table className="min-w-full text-sm">
                        <thead className="bg-slate-50 text-xs font-bold text-slate-500">
                          <tr>
                            <th className="px-3 py-2 text-left">회차</th>
                            <th className="px-3 py-2 text-left">날짜</th>
                            <th className="px-3 py-2 text-left">시간</th>
                            <th className="px-3 py-2 text-left">선생님</th>
                            <th className="px-3 py-2 text-right">금액</th>
                            <th className="px-3 py-2 text-center">삭제</th>
                          </tr>
                        </thead>
                        <tbody>
                          {editableSessions.map((s, idx) => {
                            const startDateStr = s.startAt.toISOString().split('T')[0];
                            const timeStr = s.startAt.toTimeString().slice(0, 5);
                            return (
                              <tr key={idx} className="border-t border-slate-100">
                                <td className="px-3 py-2 font-bold text-slate-700">
                                  {s.roundIndex}/{editableSessions.length}
                                </td>
                                <td className="px-3 py-2">
                                  <input
                                    type="date"
                                    className="bg-transparent border rounded-lg px-2 py-1 text-xs"
                                    value={startDateStr}
                                    onChange={(e) => {
                                      const next = [...editableSessions];
                                      const d = new Date(next[idx].startAt);
                                      const [y, m, dStr] = e.target.value.split('-').map(Number);
                                      d.setFullYear(y, m - 1, dStr);
                                      const duration =
                                        (next[idx].endAt.getTime() - next[idx].startAt.getTime()) /
                                        (1000 * 60);
                                      const end = new Date(d);
                                      end.setMinutes(end.getMinutes() + duration);
                                      next[idx] = { ...next[idx], startAt: d, endAt: end };
                                      setEditableSessions(next);
                                    }}
                                  />
                                </td>
                                <td className="px-3 py-2">
                                  <input
                                    type="time"
                                    className="bg-transparent border rounded-lg px-2 py-1 text-xs"
                                    value={timeStr}
                                    onChange={(e) => {
                                      const next = [...editableSessions];
                                      const [hh, mm] = e.target.value.split(':').map(Number);
                                      const d = new Date(next[idx].startAt);
                                      d.setHours(hh, mm, 0, 0);
                                      const duration =
                                        (next[idx].endAt.getTime() - next[idx].startAt.getTime()) /
                                        (1000 * 60);
                                      const end = new Date(d);
                                      end.setMinutes(end.getMinutes() + duration);
                                      next[idx] = { ...next[idx], startAt: d, endAt: end };
                                      setEditableSessions(next);
                                    }}
                                  />
                                </td>
                                <td className="px-3 py-2">
                                  <select
                                    className="bg-transparent border rounded-lg px-2 py-1 text-xs"
                                    value={s.teacherId}
                                    onChange={(e) => {
                                      const next = [...editableSessions];
                                      const nextTeacherId = e.target.value;
                                      const nextPrice = resolveDefaultPrice(
                                        nextTeacherId,
                                        createForm.type,
                                      );
                                      next[idx] = {
                                        ...next[idx],
                                        teacherId: nextTeacherId,
                                        price: nextPrice,
                                      };
                                      setEditableSessions(next);
                                    }}
                                  >
                                    <option value="">기본 강사</option>
                                    {teachers.map((t) => (
                                      <option key={t.id} value={t.id}>
                                        {t.name} T
                                      </option>
                                    ))}
                                  </select>
                                </td>
                                <td className="px-3 py-2 text-right">
                                  <input
                                    type="number"
                                    className="w-24 bg-transparent border rounded-lg px-2 py-1 text-xs text-right"
                                    value={s.price}
                                    onChange={(e) => {
                                      const next = [...editableSessions];
                                      next[idx] = { ...next[idx], price: Number(e.target.value) || 0 };
                                      setEditableSessions(next);
                                    }}
                                  />
                                </td>
                                <td className="px-3 py-2 text-center">
                                  <button
                                    type="button"
                                    className="px-2 py-1 rounded-full text-[11px] font-black bg-rose-50 text-rose-700 hover:bg-rose-100"
                                    onClick={() => {
                                      const next = editableSessions.filter((_, i) => i !== idx);
                                      const reindexed = next.map((row, i) => ({
                                        ...row,
                                        roundIndex: i + 1,
                                      }));
                                      setEditableSessions(reindexed);
                                    }}
                                  >
                                    삭제
                                  </button>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center h-40 text-slate-400 text-sm font-bold">
            불러오는 중...
          </div>
        ) : groups.length === 0 ? (
          <div className="flex items-center justify-center h-40 text-slate-400 text-sm font-bold">
            표시할 수업이 없습니다.
          </div>
        ) : (
          <div className="overflow-x-auto -mx-3 sm:mx-0">
            <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden min-w-[640px] sm:min-w-0">
            <table className="min-w-full text-sm">
              <thead className="bg-slate-50 text-xs font-bold text-slate-500">
                <tr>
                  <th className="px-4 py-3 text-left">수업명</th>
                  <th className="px-4 py-3 text-left">선생님</th>
                  <th className="px-4 py-3 text-left">진행</th>
                  <th className="px-4 py-3 text-left">첫 수업일</th>
                  <th className="px-4 py-3 text-left">상태</th>
                  <th className="px-4 py-3 text-right">바로가기</th>
                </tr>
              </thead>
              <tbody>
                {groups.map((g) => {
                  const firstDate = new Date(g.displayDateAt).toLocaleDateString('ko-KR', {
                    year: 'numeric',
                    month: '2-digit',
                    day: '2-digit',
                  });
                  const statusLabel = g.timeStatus === 'ongoing' ? '진행중' : '예정';
                  const teacherName = g.displayTeacherId ? teacherMap[g.displayTeacherId] || g.displayTeacherId : '미정';
                  const teacherUndecided =
                    !g.displayTeacherId || String(teacherName).trim() === '미정';
                  const rowKey = makeBundleCompositeKey(g.displayTeacherId, g.title);

                  return (
                    <tr
                      key={rowKey}
                      className={
                        teacherUndecided
                          ? "border-t border-red-200 bg-red-50/90 hover:bg-red-50"
                          : "border-t border-slate-100 hover:bg-slate-50/50"
                      }
                    >
                      <td
                        className={`px-4 py-3 font-bold ${
                          teacherUndecided ? "text-slate-900" : "text-slate-800"
                        }`}
                      >
                        {getCleanClassTitle(g.title)}
                      </td>
                      <td
                        className={`px-4 py-3 ${teacherUndecided ? 'font-bold text-red-600' : 'text-slate-600'}`}
                      >
                        {teacherName}
                      </td>
                      <td
                        className={`px-4 py-3 ${teacherUndecided ? "text-slate-800" : "text-slate-600"}`}
                      >
                        {g.roundTotal}회
                      </td>
                      <td
                        className={`px-4 py-3 ${teacherUndecided ? "text-slate-800" : "text-slate-600"}`}
                      >
                        {firstDate}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`inline-flex px-3 py-1 rounded-full text-[11px] font-bold ${
                            g.timeStatus === 'ongoing'
                              ? 'bg-blue-50 text-blue-800 border border-blue-200/80'
                              : 'bg-amber-50 text-amber-900 border border-amber-200/80'
                          }`}
                        >
                          {statusLabel}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          type="button"
                          onClick={() => {
                            // alias 그룹이면 합쳐보기 패널을 띄움
                            const aliasRule = GROUP_ALIAS_RULES.find((r) => r.aliasTitle === g.title);
                            if (aliasRule) {
                              const groupIds = aliasGroupIdsByTitle[aliasRule.aliasTitle] || [];
                              if (groupIds.length > 0) {
                                // ✅ alias는 번들 모달로 진입 (여러 group_id 토글 가능)
                                setSelectedBundle({ bundleTitle: aliasRule.aliasTitle, groupIds });
                                return;
                              }
                            }
                            // ✅ 일반 그룹도 번들 모달로 진입 (담당 + 수업명 동일 시 여러 group_id)
                            const compositeKey = makeBundleCompositeKey(g.displayTeacherId, g.title);
                            const ids = bundleGroupIdsByKey[compositeKey] || [g.groupId];
                            const titleOnly = getBundleTitleKey(g.title);
                            setSelectedBundle({ bundleTitle: titleOnly || g.title, groupIds: ids });
                          }}
                          className="inline-flex px-3 py-1.5 rounded-full text-[11px] font-bold bg-blue-600 text-white hover:bg-blue-700 transition"
                        >
                          상세
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            </div>
          </div>
        )}
      </main>

      <ClassBundlePanelV2
        visible={!!selectedBundle}
        bundleTitle={selectedBundle?.bundleTitle || ''}
        groupIds={selectedBundle?.groupIds || []}
        onClose={() => setSelectedBundle(null)}
        onChanged={() => fetchGroups()}
      />
    </div>
  );
}

export default function ClassListPageV2() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-slate-50" />}>
      <ClassListPageV2Content />
    </Suspense>
  );
}

'use client';

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { bindViewportResize } from '../lib/bindViewportResize';
import { REACT_TRAIN_VIEWPORT_CSS } from '../lib/embedViewport';
import {
  ReactTrainStartCountdownOverlay,
  REACT_TRAIN_START_COUNTDOWN_SEC,
  runReactTrainStartCountdown,
} from '../lib/reactTrainStartCountdown';
import type { ReactTrainCompleteStats } from './VisualReactionTraining';
import { setupCanvas } from '../lib/canvasUtils';
import {
  camoShapeSize,
  resolveCamouflagePosition,
  type CamouflagePlacementMode,
} from '../lib/camouflagePlacement';
import { pickCamoShapePath } from '../lib/camouflageShapes';

/** 인덱스 순서: 빨 → 파 → 초 → 노 (다른 reactTrain 레벨과 동일) */
const CAMO_COLORS = [
  { main: '#FF1744', name: 'RED' },
  { main: '#2979FF', name: 'BLUE' },
  { main: '#00E676', name: 'GREEN' },
  { main: '#FFD600', name: 'YELLOW' },
] as const;

const SPD_NAMES = ['매우 느림', '느림', '약간 느림', '보통', '약간 빠름', '빠름', '매우 빠름'];

/** 정답 도형이 완전히 드러난 뒤 다음 라운드로 넘어가기 전 유지하는 시간 — 속도 설정과 무관하게 확인할 시간을 충분히 준다 */
const HOLD_MS = 2000;

type Phase = 'NOISE' | 'REVEAL' | 'HOLD';

type CamoTarget = {
  colorIdx: number;
  shapePath: Path2D;
};

type CamoGame = {
  running: boolean;
  timeLeft: number;
  phase: Phase;
  phaseStartMs: number;
  targets: CamoTarget[];
  rounds: number;
  laneCount: [number, number, number, number];
  W: number;
  H: number;
  blockSize: number;
  edgeIdx: number;
  raf: number | null;
  timer: ReturnType<typeof setInterval> | null;
};

type Props = {
  durationSec: number;
  speedLevel: number;
  speedSec: number;
  placementMode?: CamouflagePlacementMode;
  concurrent?: 1 | 2;
  onExit: () => void;
  onComplete: (stats: ReactTrainCompleteStats) => void;
};

const css = `
.camo{position:fixed;inset:0;height:100dvh;max-height:100dvh;background:#111;color:#fff;z-index:320;display:flex;flex-direction:column;font-family:Barlow Condensed,Noto Sans KR,sans-serif;overflow:hidden}
.camo,.camo *{box-sizing:border-box}
.camo-hud{height:72px;display:flex;align-items:stretch;background:rgba(10,10,14,.92);backdrop-filter:blur(20px);border-bottom:1px solid rgba(255,255,255,.05);padding:max(0px,env(safe-area-inset-top)) clamp(12px,2.5vw,30px) 0;z-index:30;flex-shrink:0}
.camo-hc{display:flex;flex-direction:column;justify-content:center;padding:0 clamp(10px,2vw,26px);border-right:1px solid rgba(255,255,255,.05)}
.camo-hc.grow{flex:1;align-items:center;border-right:none}
.camo-hk{font-size:9px;font-weight:700;letter-spacing:.2em;color:rgba(255,255,255,.28);text-transform:uppercase}
.camo-hv{font-family:Bebas Neue,Barlow Condensed,sans-serif;font-size:clamp(22px,3.5vw,34px);letter-spacing:.04em;color:#fff;line-height:1.1}
.camo-hv.warn{animation:camow .5s ease-in-out infinite}
@keyframes camow{0%,100%{color:#ef4444;text-shadow:0 0 16px #ef4444}50%{color:#fff;text-shadow:none}}
.camo-stop{align-self:center;margin-left:auto;padding:8px 16px;border-radius:10px;border:1px solid rgba(255,255,255,.1);background:transparent;color:rgba(255,255,255,.4);font-size:13px;font-weight:700;letter-spacing:.12em;cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:6px}
.camo-stop:hover{background:rgba(255,255,255,.07);color:#fff}
.camo-play{position:relative;flex:1;min-height:0}
.camo-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.camo-msg{position:absolute;left:50%;top:9%;transform:translateX(-50%);z-index:20;font-size:clamp(18px,3.4vw,32px);font-weight:900;color:#fff;text-shadow:0 0 20px rgba(0,0,0,.8);background:rgba(0,0,0,.5);padding:10px 28px;border-radius:999px;pointer-events:none;opacity:0;transition:opacity .3s ease;white-space:nowrap}
.camo-msg.show{opacity:1}
${REACT_TRAIN_VIEWPORT_CSS}
`;

export function CamouflageReactionTraining({
  durationSec,
  speedLevel: _speedLevel,
  speedSec,
  placementMode = 'center',
  concurrent = 1,
  onExit,
  onComplete,
}: Props) {
  const cvRef = useRef<HTMLCanvasElement>(null);
  const playRef = useRef<HTMLDivElement>(null);
  const hudTimeRef = useRef<HTMLDivElement>(null);
  const hudRoundsRef = useRef<HTMLDivElement>(null);
  const msgRef = useRef<HTMLDivElement>(null);
  const [warn, setWarn] = useState(false);
  const [countdown, setCountdown] = useState(REACT_TRAIN_START_COUNTDOWN_SEC);
  const gRef = useRef<CamoGame | null>(null);
  const placementModeRef = useRef(placementMode);
  useEffect(() => {
    placementModeRef.current = placementMode;
  }, [placementMode]);
  const onCompleteRef = useRef(onComplete);
  const onExitRef = useRef(onExit);
  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);
  useEffect(() => {
    onExitRef.current = onExit;
  }, [onExit]);

  /** 위장 해제(REVEAL) 소요 시간 — 신호 속도 설정과 직접 연결 */
  const fallTimeSec = Math.max(1, Math.min(6, Number.isFinite(speedSec) ? speedSec : 5));
  const revealMs = fallTimeSec * 1000;
  const lv = Math.max(1, Math.min(7, Math.round(7 - ((fallTimeSec - 1) * 6) / 5)));
  const spName = SPD_NAMES[lv - 1] ?? '보통';
  /** 노이즈 대기 시간: 5초 고정에 맞춘 난이도 단계 */
  const noiseMs = Math.max(700, 1700 - (lv - 1) * 140);

  const stopGame = useCallback(() => {
    const g = gRef.current;
    if (!g?.running) return;
    g.running = false;
    if (g.raf != null) cancelAnimationFrame(g.raf);
    if (g.timer) clearInterval(g.timer);
    onCompleteRef.current({
      stims: g.rounds,
      maxCombo: g.rounds,
      laneCount: [...g.laneCount] as [number, number, number, number],
    });
  }, []);

  const endGame = useCallback(() => {
    const g = gRef.current;
    if (!g) return;
    g.running = false;
    if (g.raf != null) cancelAnimationFrame(g.raf);
    if (g.timer) clearInterval(g.timer);
    onCompleteRef.current({
      stims: g.rounds,
      maxCombo: g.rounds,
      laneCount: [...g.laneCount] as [number, number, number, number],
    });
  }, []);

  useEffect(() => {
    const cv = cvRef.current;
    const play = playRef.current;
    if (!cv || !play) return;

    const g: CamoGame = {
      running: true,
      timeLeft: durationSec,
      phase: 'NOISE',
      phaseStartMs: 0,
      targets: [],
      rounds: 0,
      laneCount: [0, 0, 0, 0],
      W: 0,
      H: 0,
      blockSize: 20,
      edgeIdx: 0,
      raf: null,
      timer: null,
    };
    gRef.current = g;

    const calcLayout = () => {
      const w = play.clientWidth;
      const h = play.clientHeight;
      if (w <= 0 || h <= 0) return;
      const r = setupCanvas(cv, w, h);
      g.W = r.cssW;
      g.H = r.cssH;
      // 도형 실루엣이 격자에 묻히지 않도록 항상 고운 블록을 쓴다.
      // navigator.hardwareConcurrency 기반 저사양 판정은 브라우저별 편차가 커서 신뢰하지 않는다.
      g.blockSize = g.W < 600 ? 9 : g.W > 1200 ? 15 : 12;
    };

    const updateHudTime = () => {
      const m = String(Math.floor(g.timeLeft / 60)).padStart(2, '0');
      const s = String(g.timeLeft % 60).padStart(2, '0');
      if (hudTimeRef.current) hudTimeRef.current.textContent = `${m}:${s}`;
      setWarn(g.timeLeft <= 10);
    };
    updateHudTime();
    if (hudRoundsRef.current) hudRoundsRef.current.textContent = '0';

    const newTargets = () => {
      const size = camoShapeSize(g.W, g.H);
      const count = concurrent === 2 ? 2 : 1;
      g.targets = Array.from({ length: count }, (_, idx) => {
        const edge = g.edgeIdx + idx;
        const { cx, cy } = resolveCamouflagePosition(
          placementModeRef.current,
          g.W,
          g.H,
          edge,
          size,
        );
        return {
          colorIdx: Math.floor(Math.random() * 4),
          shapePath: pickCamoShapePath(cx, cy, size),
        };
      });
      if (placementModeRef.current === 'variant') {
        g.edgeIdx = (g.edgeIdx + count) % 4;
      }
    };

    const startRound = () => {
      calcLayout();
      newTargets();
      g.phase = 'NOISE';
      g.phaseStartMs = performance.now();
      if (msgRef.current) {
        msgRef.current.textContent = '어떤 색깔이 숨어있을까요?';
        msgRef.current.classList.add('show');
      }
    };

    const loop = (now: number) => {
      if (!gRef.current?.running) return;
      const ctx = cv.getContext('2d');
      if (!ctx) return;

      const elapsed = now - g.phaseStartMs;
      if (g.phase === 'NOISE' && elapsed >= noiseMs) {
        g.phase = 'REVEAL';
        g.phaseStartMs = now;
      } else if (g.phase === 'REVEAL' && elapsed >= revealMs) {
        g.phase = 'HOLD';
        g.phaseStartMs = now;
        g.rounds += g.targets.length;
        for (const target of g.targets) {
          g.laneCount[target.colorIdx]++;
        }
        if (hudRoundsRef.current) hudRoundsRef.current.textContent = String(g.rounds);
        if (msgRef.current) msgRef.current.textContent = '정답 확인!';
      } else if (g.phase === 'HOLD' && elapsed >= HOLD_MS) {
        startRound();
      }

      let progress = 0;
      if (g.phase === 'REVEAL') progress = Math.min(elapsed / revealMs, 1);
      else if (g.phase === 'HOLD') progress = 1;

      const bs = g.blockSize;
      const cols = Math.ceil(g.W / bs);
      const rows = Math.ceil(g.H / bs);
      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const x = col * bs;
          const y = row * bs;
          const cx = x + bs / 2;
          const cy = y + bs / 2;
          let targetColorIdx: number | null = null;
          if (g.phase !== 'NOISE') {
            for (const target of g.targets) {
              if (ctx.isPointInPath(target.shapePath, cx, cy)) {
                targetColorIdx = target.colorIdx;
                break;
              }
            }
          }
          let cellColor: string = CAMO_COLORS[Math.floor(Math.random() * 4)].main;
          if (targetColorIdx !== null && Math.random() < progress) cellColor = CAMO_COLORS[targetColorIdx].main;
          ctx.fillStyle = cellColor;
          ctx.fillRect(x, y, bs, bs);
        }
      }

      g.raf = requestAnimationFrame(loop);
    };

    const beginGame = () => {
      if (!gRef.current?.running) return;
      calcLayout();
      startRound();
      const endsAtMs = performance.now() + durationSec * 1000;
      g.timer = setInterval(() => {
        const newLeft = Math.max(0, Math.ceil((endsAtMs - performance.now()) / 1000));
        if (g.timeLeft !== newLeft) {
          g.timeLeft = newLeft;
          updateHudTime();
        }
        if (g.timeLeft <= 0) {
          if (g.timer) clearInterval(g.timer);
          g.timer = null;
          endGame();
        }
      }, 250);
      g.raf = requestAnimationFrame(loop);
    };

    const stopCountdown = runReactTrainStartCountdown({
      onTick: setCountdown,
      onDone: beginGame,
    });

    const unbindResize = bindViewportResize(play, () => calcLayout());

    return () => {
      stopCountdown();
      unbindResize();
      g.running = false;
      if (g.timer) clearInterval(g.timer);
      if (g.raf != null) cancelAnimationFrame(g.raf);
    };
  }, [concurrent, durationSec, endGame, noiseMs, revealMs]);

  return (
    <div className="camo">
      <style>{css}</style>
      <div className="camo-hud">
        <div className="camo-hc">
          <div className="camo-hk">Time</div>
          <div className={`camo-hv${warn ? ' warn' : ''}`} ref={hudTimeRef} />
        </div>
        <div className="camo-hc">
          <div className="camo-hk">Rounds</div>
          <div className="camo-hv" ref={hudRoundsRef} />
        </div>
        <div className="camo-hc grow">
          <div className="camo-hv" style={{ fontSize: 'clamp(12px,2vw,19px)' }}>
            CAMOUFLAGE · {spName}{placementMode === 'variant' ? ' · 변형' : ''}
          </div>
        </div>
        <div className="camo-hc" style={{ borderRight: 'none', borderLeft: '1px solid rgba(255,255,255,.05)' }}>
          <button type="button" className="camo-stop" onClick={stopGame}>
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" width="14" height="14" aria-hidden>
              <rect x="6" y="6" width="4" height="12" rx="1" />
              <rect x="14" y="6" width="4" height="12" rx="1" />
            </svg>
            STOP
          </button>
        </div>
      </div>
      <div ref={playRef} className="camo-play">
        <canvas className="camo-canvas" ref={cvRef} />
        <ReactTrainStartCountdownOverlay countdown={countdown} />
        <div className="camo-msg" ref={msgRef} />
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Play,
  Pause,
  RefreshCw,
  Settings,
  Edit3,
  Check,
  Music,
  Image as ImageIcon,
  X,
  Zap,
  Megaphone,
  Lightbulb,
  AlertCircle,
  ArrowRight,
  Ear,
  Mic,
} from 'lucide-react';
import { preloadChallengeBGM, startChallengeBGM, stopChallengeBGM } from '@/app/lib/admin/audio/challengeBGM';

export interface SpokeduRhythmGameProps {
  soundOn?: boolean;
  allowEdit?: boolean;
  bgmPath?: string;
  /** BGM 원곡 BPM. 있으면 재생 속도 = 화면 BPM / 이 값 (한 곡을 여러 BPM에 맞춰 재생) */
  bgmSourceBpm?: number | null;
  initialBpm?: number;
  initialLevel?: number;
  initialGrid?: string[];
  /** 1~4단계 그리드 전체 (있으면 initialLevel/initialGrid 대신 사용) */
  initialLevelData?: Record<number, string[]>;
  onEnd?: () => void;
  onPresetChange?: (data: { bpm: number; level: number; grid: string[]; gridsByLevel?: Record<number, string[]> }) => void;
  /** true면 BPM 조절 불가(주차 픽스·BGM 비트 맞출 때 사용) */
  lockBpm?: boolean;
  /** true면 마운트 후 재생 버튼 없이 바로 카운트다운·플레이 시작 (구독자 전체 재생 등) */
  autoStart?: boolean;
  /** (예약) BGM 시작 오프셋 — 현재 재생 로직에는 사용하지 않음. 스튜디오 저장값만 유지. */
  bgmStartOffsetMs?: number;
}

const MAX_LEVELS = 4;
const ROUNDS_PER_LEVEL = 4;
const BEATS_PER_PHASE = 8;
const BEATS_PER_ROUND = 16;
/** 허용 BPM (4종). 미지원 값(80/160 등)은 초기화 시 100으로 정규화됨. */
const bpmOptions = [100, 120, 150, 180];
/** 180 선택 시 1단계 21.05초 동기화용 미세조정. 플레이 화면에는 180만 노출. (BGM·레벨 전환 t0 누적 오차 보정과는 별개의 경험적 값) */
const BPM_180_SYNC = 182.4;
/** 150 선택 시 정박 미세조정. 3~4단계 살짝 밀림 보정용으로 소폭 상향. */
const BPM_150_SYNC = 150.5;
function getEffectiveBpm(displayBpm: number): number {
  if (displayBpm === 180) return BPM_180_SYNC;
  if (displayBpm === 150) return BPM_150_SYNC;
  return displayBpm;
}
const SCHEDULE_AHEAD_TIME = 0.1;
/** BGM play() 후 실제 스피커 출력까지 지연 보정(초). 환경에 따라 0.03~0.08 정도. */
const BGM_OUTPUT_LATENCY = 0.04;

/** 1단계 시작 전 고정 카운트다운(ms). 끝나면 노래·영상 동시 시작. */
const INITIAL_COUNTDOWN_MS = 3000;
/** 레벨 사이: rest 3초만 표시 후 바로 다음 단계. 2단계부터 카운트다운 없음. */
const BETWEEN_LEVEL_MS = 3000;
/** 3초 카운트다운에서 4,3,2,1 표시 간격(ms). */
const COUNTDOWN_TICK_MS = 750;

/** 레벨 완료 → 다음 beat 0까지 rest 3초 고정. */
function getTransitionDurationMs(_bpm: number, _bgmSourceBpm?: number | null): number {
  void _bpm;
  void _bgmSourceBpm;
  return BETWEEN_LEVEL_MS;
}

/** 초반 3초 + 4단계 플레이(256비트) + 3회 전환(6초) + 아웃트로(0.6s) 총 재생 시간(초). 오프셋 없음. */
function getTotalChallengeDurationSec(bpm: number, _bgmSourceBpm?: number | null): number {
  void _bgmSourceBpm;
  const beatSec = 60 / bpm;
  const levelBeats = MAX_LEVELS * ROUNDS_PER_LEVEL * BEATS_PER_ROUND;
  return (
    INITIAL_COUNTDOWN_MS / 1000 +
    levelBeats * beatSec +
    3 * (BETWEEN_LEVEL_MS / 1000) +
    0.6
  );
}

/** 한 레벨(64비트) 플레이 길이 — 벽시계 ms. BGM은 1·2·3·4단계 모두 파일 처음부터 이 길이만큼 같은 구간을 반복 재생. */
function getBgmDurationMsPerLevel(bpm: number): number {
  const beatSec = 60 / bpm;
  const beatsPerLevel = ROUNDS_PER_LEVEL * BEATS_PER_ROUND;
  return Math.round(beatsPerLevel * beatSec * 1000);
}

/** 각 단계 첫 페이지 = 룰(8칸 구성). 2~5라운드는 이 배열을 셔플만 함. */
const defaultLevels: Record<number, string[]> = {
  1: ['앞', '뒤', '앞', '뒤', '앞', '뒤', '앞', '뒤'], // 1단계: 앞/뒤만
  2: ['앞', '뒤', '앞', '뒤', '앞', '뒤', '오른쪽', '왼쪽'], // 2단계: 앞/뒤 6, 오른쪽/왼쪽 2
  3: ['앞', '뒤', '앞', '뒤', '오른쪽', '왼쪽', '오른쪽', '왼쪽'], // 3단계: 앞/뒤 4, 오른쪽/왼쪽 4
  4: ['앞', '뒤', '오른쪽', '왼쪽', '오른쪽', '왼쪽', '좌우', '앞뒤'], // 4단계: 앞/뒤 2, 오른쪽/왼쪽 4, 좌우 1, 앞뒤 1
};

export function SpokeduRhythmGame({
  soundOn = false,
  allowEdit = true,
  bgmPath,
  bgmSourceBpm,
  initialBpm,
  initialLevel,
  initialGrid,
  initialLevelData,
  onEnd,
  onPresetChange,
  lockBpm = false,
  autoStart = false,
  bgmStartOffsetMs = 0,
}: SpokeduRhythmGameProps) {
  void bgmStartOffsetMs;
  const [isPlaying, setIsPlaying] = useState(false);
  const [isCountingDown, setIsCountingDown] = useState(false);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [isFinished, setIsFinished] = useState(false);
  /** 4단계 종료 후 rest 구간(큰 숫자 1 숨김 + 아웃트로 직전). finishGame()에서만 isFinishingRef 설정. */
  const [isFinishingRest, setIsFinishingRest] = useState(false);
  const isFinishingRestRef = useRef(false);
  /** 레벨 사이 rest 3초 동안 표시할 카운트다운 (3 → 2 → 1). null이면 표시 안 함. */
  const [restCountdown, setRestCountdown] = useState<number | null>(null);

  const [currentBeat, setCurrentBeat] = useState(-1);
  const [roundInLevel, setRoundInLevel] = useState(1);
  const [currentLevel, setCurrentLevel] = useState(() =>
    Math.min(MAX_LEVELS, Math.max(1, initialLevel ?? 1))
  );
  const [totalBeatsPlayed, setTotalBeatsPlayed] = useState(0);

  const [bpm, setBpm] = useState(() => {
    const v = initialBpm ?? 100;
    if (typeof v === 'number' && Math.abs(v - BPM_180_SYNC) < 0.5) return 180;
    if (typeof v === 'number' && Math.abs(v - BPM_150_SYNC) < 0.5) return 150;
    return bpmOptions.includes(v) ? v : 100;
  });
  const [isEditing, setIsEditing] = useState(false);

  const nextNoteTimeRef = useRef(0.0);
  /** 스케줄러 시작 시각(AudioContext). 매 비트를 startTime + beatIndex*beatSec 로 계산해 누적 오차 제거. */
  const schedulerStartTimeRef = useRef(0.0);
  const currentBeatIndexRef = useRef(0);
  const levelRoundCountRef = useRef(1);
  const timerIDRef = useRef<number | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const bpmRef = useRef(bpm);
  const bgmSourceBpmRef = useRef(bgmSourceBpm);
  const runIdRef = useRef(0);
  const isFinishingRef = useRef(false);
  const isTransitioningRef = useRef(false);
  const isPlayingRef = useRef(false);
  const startCountdownRef = useRef<() => void>(() => {});
  const schedulerRef = useRef<() => void>(() => {});
  /** 초반 3초 카운트다운 끝에 호출(스케줄러 시작 직전). BGM 재생을 여기서 하면 노래·영상 동시 시작 보장. */
  const onCountdownEndRef = useRef<(() => void) | null>(null);

  const [levelData, setLevelData] = useState<Record<number, string[]>>(() => {
    const base = { ...defaultLevels };
    if (initialLevelData && typeof initialLevelData === 'object') {
      for (let lv = 1; lv <= MAX_LEVELS; lv++) {
        if (Array.isArray(initialLevelData[lv]) && initialLevelData[lv].length > 0) {
          base[lv] = initialLevelData[lv].slice(0, 8);
        }
      }
    } else if (initialGrid != null && initialLevel != null) {
      base[initialLevel] = [...initialGrid];
    }
    return base;
  });
  const [shuffledGrid, setShuffledGrid] = useState<string[]>(() => {
    const firstGrid =
      initialLevelData && Array.isArray(initialLevelData[1]) && initialLevelData[1].length > 0
        ? initialLevelData[1]
        : initialGrid ?? defaultLevels[initialLevel ?? 1] ?? defaultLevels[1];
    return [...firstGrid];
  });
  /** 셔플 시 그리드 셀 DOM을 확실히 갱신하기 위한 레이아웃 키(고정 슬롯 + 셔플 세대). */
  const [gridLayoutKey, setGridLayoutKey] = useState(0);

  const currentLevelRef = useRef(currentLevel);
  const levelDataRef = useRef(levelData);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadTargetIndex, setUploadTargetIndex] = useState<number | null>(null);
  const [composingCell, setComposingCell] = useState<{ index: number; value: string } | null>(null);

  const shuffleArray = useCallback((array: string[]) => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
  }, []);

  const setGridFromShuffle = useCallback(
    (arr: string[]) => {
      setShuffledGrid(shuffleArray(arr));
      setGridLayoutKey((k) => k + 1);
    },
    [shuffleArray]
  );

  const isImage = (content: string) => {
    if (typeof content !== 'string') return false;
    const t = content.trim();
    if (t.startsWith('data:image')) return true;
    if (t.startsWith('http://') || t.startsWith('https://')) return true;
    if (t.startsWith('//')) return true;
    return false;
  };

  useEffect(() => {
    isPlayingRef.current = isPlaying;
  }, [isPlaying]);

  useEffect(() => {
    if (isPlayingRef.current) return;
    if (initialBpm != null) {
      const v = initialBpm;
      if (Math.abs(v - BPM_180_SYNC) < 0.5) setBpm(180);
      else if (Math.abs(v - BPM_150_SYNC) < 0.5) setBpm(150);
      else setBpm(bpmOptions.includes(v) ? v : 100);
    }
    if (initialLevel != null)
      setCurrentLevel(Math.min(MAX_LEVELS, Math.max(1, initialLevel)));
    if (initialLevelData && typeof initialLevelData === 'object') {
      setLevelData((prev) => {
        const next = { ...prev };
        for (let lv = 1; lv <= MAX_LEVELS; lv++) {
          if (Array.isArray(initialLevelData[lv]) && initialLevelData[lv].length > 0) {
            next[lv] = initialLevelData[lv].slice(0, 8);
          }
        }
        return next;
      });
      const first = initialLevelData[1];
      if (Array.isArray(first) && first.length > 0) setShuffledGrid([...first]);
    } else if (initialGrid != null && initialLevel != null) {
      setLevelData((prev) => ({ ...prev, [initialLevel]: initialGrid }));
      setShuffledGrid([...initialGrid]);
    }
    runIdRef.current++;
    if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
    timerIDRef.current = null;
    setIsPlaying(false);
    setIsCountingDown(false);
    isTransitioningRef.current = false;
    setIsTransitioning(false);
    setIsFinished(false);
    setCurrentBeat(-1);
    setRoundInLevel(1);
    setTotalBeatsPlayed(0);
    currentBeatIndexRef.current = 0;
    levelRoundCountRef.current = 1;
    isFinishingRef.current = false;
  }, [initialBpm, initialLevel, initialGrid, initialLevelData]);

  useEffect(() => {
    currentLevelRef.current = currentLevel;
    levelDataRef.current = levelData;
  }, [currentLevel, levelData]);

  useEffect(() => {
    if (initialGrid != null && initialLevel != null && !isPlaying) {
      setShuffledGrid([...initialGrid]);
    }
  }, [initialGrid, initialLevel, isPlaying]);

  useEffect(() => {
    bpmRef.current = getEffectiveBpm(bpm);
  }, [bpm]);

  useEffect(() => {
    bgmSourceBpmRef.current = bgmSourceBpm;
  }, [bgmSourceBpm]);

  const playClick = useCallback(
    (time: number) => {
      if (!soundOn || !audioContextRef.current) return;
      const ctx = audioContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.setValueAtTime(1000, time);
      osc.type = 'square';
      gain.gain.setValueAtTime(0, time);
      gain.gain.linearRampToValueAtTime(0.3, time + 0.005);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.08);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(time);
      osc.stop(time + 0.1);
    },
    [soundOn]
  );

  const playGuideTone = useCallback(
    (time: number) => {
      if (!soundOn || !audioContextRef.current) return;
      const ctx = audioContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.setValueAtTime(523.25, time);
      osc.type = 'sine';
      gain.gain.setValueAtTime(0, time);
      gain.gain.linearRampToValueAtTime(0.4, time + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.1);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(time);
      osc.stop(time + 0.15);
    },
    [soundOn]
  );

  const playWhistle = useCallback(
    (time: number, isStrong: boolean) => {
      if (!soundOn || !audioContextRef.current) return;
      const ctx = audioContextRef.current;
      const t = Math.max(time, ctx.currentTime + 0.01);
      const osc1 = ctx.createOscillator();
      const osc2 = ctx.createOscillator();
      const gainNode = ctx.createGain();
      osc1.type = 'triangle';
      osc2.type = 'triangle';
      const baseFreq = isStrong ? 2800 : 2200;
      const duration = isStrong ? 0.15 : 0.08;
      osc1.frequency.setValueAtTime(baseFreq, t);
      osc2.frequency.setValueAtTime(baseFreq + (isStrong ? 200 : 150), t);
      gainNode.gain.setValueAtTime(0, t);
      gainNode.gain.linearRampToValueAtTime(isStrong ? 0.5 : 0.35, t + 0.005);
      gainNode.gain.exponentialRampToValueAtTime(0.001, t + duration);
      osc1.connect(gainNode);
      osc2.connect(gainNode);
      gainNode.connect(ctx.destination);
      osc1.start(t);
      osc2.start(t);
      osc1.stop(t + duration);
      osc2.stop(t + duration);
    },
    [soundOn]
  );

  const nextNote = useCallback(() => {
    currentBeatIndexRef.current++;
    if (currentBeatIndexRef.current === BEATS_PER_ROUND) {
      currentBeatIndexRef.current = 0;
      levelRoundCountRef.current++;
      if (levelRoundCountRef.current > ROUNDS_PER_LEVEL) return 'LEVEL_COMPLETE';
      return 'NEXT_ROUND';
    }
    return 'CONTINUE';
  }, []);

  const finishGame = useCallback(() => {
    if (isFinishingRef.current) return;
    isFinishingRef.current = true;
    isFinishingRestRef.current = false;
    runIdRef.current++;
    if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
    stopChallengeBGM();
    setIsPlaying(false);
    setIsCountingDown(false);
    setIsFinishingRest(false);
    isTransitioningRef.current = false;
    setIsTransitioning(false);
    setIsFinished(true);
    setCurrentBeat(-1);
    onEnd?.();
  }, [onEnd]);

  const handleLevelComplete = useCallback((lastBeatScheduledTime?: number) => {
    if (isTransitioningRef.current) return;
    if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
    const levelWhenComplete = currentLevelRef.current;

    if (levelWhenComplete >= MAX_LEVELS) {
      // 마지막 비트(15) 호각 후 rest: lastBeatScheduledTime 기준으로 최소 220ms 대기
      const ctx = audioContextRef.current;
      const now = ctx?.currentTime ?? 0;
      const afterLastBeatMs = lastBeatScheduledTime != null ? Math.max(0, (lastBeatScheduledTime - now) * 1000) + 220 : 220;
      const finishDelayMs = afterLastBeatMs;
      setTimeout(() => {
        runIdRef.current++;
        const myRunId = runIdRef.current;
        isFinishingRestRef.current = true;
        setIsFinishingRest(true);
        setCurrentBeat(-1);
        setRoundInLevel(ROUNDS_PER_LEVEL);
        setTimeout(() => {
          if (myRunId !== runIdRef.current) return;
          finishGame();
        }, 600);
      }, finishDelayMs);
      return;
    }

    // 마지막 호각(비트 15) 이후에 rest 표시 — lastBeatScheduledTime이 있으면 그 시각 이후로 대기 후 3초 rest
    const oneBeatMs = Math.round((60 / bpmRef.current) * 1000);
    const transitionMs = getTransitionDurationMs(bpmRef.current, bgmSourceBpmRef.current);
    const ctx = audioContextRef.current;
    const now = ctx?.currentTime ?? 0;
    const waitAfterLastBeatMs = lastBeatScheduledTime != null ? Math.max(0, (lastBeatScheduledTime - now) * 1000) + 80 : 0;
    const delayMs = Math.max(oneBeatMs, waitAfterLastBeatMs);
    setTimeout(() => {
      runIdRef.current++;
      const myRunId = runIdRef.current;
      setCurrentBeat(-1);
      isTransitioningRef.current = true;
      setIsTransitioning(true);
      setRestCountdown(3);
      stopChallengeBGM();

      setTimeout(() => {
        if (myRunId !== runIdRef.current) return;
        setRestCountdown(2);
      }, 1000);
      setTimeout(() => {
        if (myRunId !== runIdRef.current) return;
        setRestCountdown(1);
      }, 2000);

      // 3초 후 다음 레벨: BGM은 항상 파일 0초부터 1단계와 동일 길이만 재생(곡 앞 구간 반복)
      setTimeout(() => {
        if (myRunId !== runIdRef.current) return;
        const nextLvl = levelWhenComplete + 1;
        currentLevelRef.current = nextLvl;
        levelDataRef.current = levelData;
        levelRoundCountRef.current = 1;
        setCurrentLevel(nextLvl);
        setRoundInLevel(1);
        setGridFromShuffle(levelData[nextLvl] ?? defaultLevels[nextLvl]);
        isTransitioningRef.current = false;
        setIsTransitioning(false);
        setRestCountdown(null);

        const startSchedulerNow = () => {
          if (myRunId !== runIdRef.current) return;
          if (audioContextRef.current) {
            // 매 레벨마다 ctx.currentTime 기준 절대 시각(이전 단계와 선행시간이 누적되지 않음)
            const t0 = audioContextRef.current.currentTime + 0.1 + BGM_OUTPUT_LATENCY;
            schedulerStartTimeRef.current = t0;
            nextNoteTimeRef.current = t0;
            currentBeatIndexRef.current = 0;
            schedulerRef.current();
          }
        };

        if (bgmPath) {
          const bpm = bpmRef.current;
          const playbackRate =
            typeof bgmSourceBpmRef.current === 'number' && bgmSourceBpmRef.current > 0
              ? bpm / bgmSourceBpmRef.current
              : 1;
          const durationMs = getBgmDurationMsPerLevel(bpm);
          startChallengeBGM(bgmPath, 0, durationMs, playbackRate)
            .then(startSchedulerNow)
            .catch(() => startSchedulerNow());
        } else {
          startSchedulerNow();
        }
      }, transitionMs);
    }, delayMs);
  }, [levelData, finishGame, bpm, bgmPath, setGridFromShuffle]);

  const scheduleNote = useCallback(
    (beatNumber: number, time: number, currentLevelRound: number) => {
      const myRunId = runIdRef.current;

      if (audioContextRef.current && audioContextRef.current.state === 'running') {
        if (beatNumber < 0) {
          playClick(time);
        } else if (beatNumber < 8) {
          playGuideTone(time);
        } else {
          const actionBeatIndex = beatNumber - 8;
          playWhistle(time, actionBeatIndex === 0);
        }
      }

      const drawTime = time - (audioContextRef.current?.currentTime ?? 0);
      const level = currentLevelRef.current;
      // 4단계 4라운드: 누적 드리프트 보정 — 초록을 호루라기 소리보다 약간 앞당겨서 맞춤
      const pullMs =
        level === MAX_LEVELS && currentLevelRound >= ROUNDS_PER_LEVEL ? 80 : 0;
      const delayMs = Math.max(0, drawTime * 1000 - pullMs);

      setTimeout(() => {
        if (myRunId !== runIdRef.current) return;
        if (isFinishingRef.current) return;
        if (isFinishingRestRef.current) return;
        if (isTransitioningRef.current) return;

        if (beatNumber === 0 && currentLevelRound > 1) {
          const lv = currentLevelRef.current;
          const data = levelDataRef.current;
          setGridFromShuffle(data[lv] ?? defaultLevels[lv]);
        }

        setCurrentBeat(beatNumber);
        if (beatNumber >= 0) {
          setRoundInLevel(currentLevelRound);
          if (beatNumber >= 8) {
            setTotalBeatsPlayed((prev) => prev + 1);
          }
        }
      }, delayMs);
    },
    [playClick, playGuideTone, playWhistle, setGridFromShuffle]
  );

  const scheduler = useCallback(() => {
    if (!audioContextRef.current) return;
    const ctx = audioContextRef.current;
    const now = ctx.currentTime;
    const secondsPerBeat = 60.0 / bpmRef.current;

    while (
      nextNoteTimeRef.current <
      now + SCHEDULE_AHEAD_TIME
    ) {
      const lr = levelRoundCountRef.current;
      const b = currentBeatIndexRef.current;

      if (lr > ROUNDS_PER_LEVEL) {
        handleLevelComplete();
        break;
      }

      const scheduledTime = nextNoteTimeRef.current;
      scheduleNote(b, scheduledTime, lr);
      const status = nextNote();
      const levelBeatIndex = (levelRoundCountRef.current - 1) * BEATS_PER_ROUND + currentBeatIndexRef.current;
      nextNoteTimeRef.current = schedulerStartTimeRef.current + levelBeatIndex * secondsPerBeat;

      if (status === 'LEVEL_COMPLETE') {
        handleLevelComplete(scheduledTime);
        return;
      }
    }

    timerIDRef.current = requestAnimationFrame(() => schedulerRef.current());
  }, [scheduleNote, nextNote, handleLevelComplete]);

  useEffect(() => {
    schedulerRef.current = scheduler;
  }, [scheduler]);

  /** 초반 3초 카운트다운(4,3,2,1) 후 beat 0부터 스케줄러 시작. 레벨 사이 전환에서는 사용하지 않음. */
  const startCountdown = useCallback(() => {
    const myRunId = runIdRef.current;
    setIsCountingDown(true);
    setCurrentBeat(-4);
    currentBeatIndexRef.current = -4;

    setTimeout(() => {
      if (myRunId !== runIdRef.current) return;
      setCurrentBeat(-3);
    }, COUNTDOWN_TICK_MS);
    setTimeout(() => {
      if (myRunId !== runIdRef.current) return;
      setCurrentBeat(-2);
    }, COUNTDOWN_TICK_MS * 2);
    setTimeout(() => {
      if (myRunId !== runIdRef.current) return;
      setCurrentBeat(-1);
    }, COUNTDOWN_TICK_MS * 3);
    setTimeout(() => {
      if (myRunId !== runIdRef.current) return;
      if (isFinishingRef.current) return;
      const fn = onCountdownEndRef.current;
      onCountdownEndRef.current = null;
      const startScheduler = () => {
        if (myRunId !== runIdRef.current) return;
        if (isFinishingRef.current) return;
        setIsCountingDown(false);
        if (audioContextRef.current) {
          // 1단계 시작: 레벨 전환과 동일하게 ctx 기준 절대 t0(누적 아님)
          const t0 = audioContextRef.current.currentTime + 0.1 + BGM_OUTPUT_LATENCY;
          schedulerStartTimeRef.current = t0;
          nextNoteTimeRef.current = t0;
          currentBeatIndexRef.current = 0;
          scheduler();
        }
      };
      if (fn) {
        Promise.resolve(fn()).then(startScheduler).catch(() => startScheduler());
      } else {
        startScheduler();
      }
    }, INITIAL_COUNTDOWN_MS);
  }, [scheduler]);

  useEffect(() => {
    startCountdownRef.current = startCountdown;
  }, [startCountdown]);

  useEffect(() => {
    if (bgmPath) preloadChallengeBGM(bgmPath);
  }, [bgmPath]);

  useEffect(() => {
    return () => {
      onCountdownEndRef.current = null;
      if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
      runIdRef.current++;
      stopChallengeBGM();
    };
  }, []);

  useEffect(() => {
    if (!isPlaying && !isTransitioning) {
      const grid = levelData[currentLevel] ?? defaultLevels[currentLevel];
      setShuffledGrid([...grid]);
    }
  }, [currentLevel, levelData, isPlaying, isTransitioning]);

  useEffect(() => {
    if (isCountingDown && roundInLevel === 1) {
      setGridFromShuffle(levelData[currentLevel] ?? defaultLevels[currentLevel]);
    }
  }, [isCountingDown, roundInLevel, levelData, currentLevel, setGridFromShuffle]);

  const resetGame = useCallback(() => {
    runIdRef.current++;
    onCountdownEndRef.current = null;
    isFinishingRestRef.current = false;
    if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
    stopChallengeBGM();
    setIsPlaying(false);
    setIsCountingDown(false);
    setIsFinishingRest(false);
    setRestCountdown(null);
    isTransitioningRef.current = false;
    setIsTransitioning(false);
    setIsFinished(false);
    isFinishingRef.current = false;
    setCurrentBeat(-1);
    setCurrentLevel(Math.min(MAX_LEVELS, Math.max(1, initialLevel ?? 1)));
    setRoundInLevel(1);
    setTotalBeatsPlayed(0);
    currentBeatIndexRef.current = 0;
    levelRoundCountRef.current = 1;
    const lv = Math.min(MAX_LEVELS, Math.max(1, initialLevel ?? currentLevel ?? 1));
    const grid = levelData[lv] ?? defaultLevels[lv];
    setShuffledGrid([...grid]);
  }, [currentLevel, levelData, initialLevel]);

  const togglePlay = useCallback(async () => {
    if (isFinished) {
      resetGame();
      return;
    }

    if (!isPlaying) {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext ||
          (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
      }
      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      setIsPlaying(true);

      if (
        currentLevel === 1 &&
        roundInLevel === 1 &&
        currentBeat === -1 &&
        !isTransitioning
      ) {
        runIdRef.current++;
        levelRoundCountRef.current = 1;
        setRoundInLevel(1);
        setTotalBeatsPlayed(0);
        isFinishingRef.current = false;
        setGridFromShuffle(levelData[1] ?? defaultLevels[1]);
        if (bgmPath) {
          const currentBpm = bpmRef.current;
          const currentSourceBpm = bgmSourceBpmRef.current;
          const playbackRate =
            typeof currentSourceBpm === 'number' && currentSourceBpm > 0
              ? currentBpm / currentSourceBpm
              : 1;
          const levelBgmMs = getBgmDurationMsPerLevel(currentBpm);
          onCountdownEndRef.current = () =>
            startChallengeBGM(bgmPath, 0, levelBgmMs, playbackRate);
        }
        startCountdown();
      } else {
        runIdRef.current++;
        const ctx = audioContextRef.current;
        if (ctx) {
          const now = ctx.currentTime + 0.1;
          const secPerBeat = 60 / bpmRef.current;
          schedulerStartTimeRef.current = now - currentBeatIndexRef.current * secPerBeat;
          nextNoteTimeRef.current = now;
        }
        scheduler();
      }
    } else {
      runIdRef.current++;
      onCountdownEndRef.current = null;
      stopChallengeBGM();
      setIsPlaying(false);
      if (timerIDRef.current) cancelAnimationFrame(timerIDRef.current);
    }
  }, [
    isFinished,
    isPlaying,
    currentLevel,
    roundInLevel,
    currentBeat,
    isTransitioning,
    resetGame,
    startCountdown,
    scheduler,
    bgmPath,
    bgmSourceBpm,
    bpm,
    levelData,
    setGridFromShuffle,
  ]);

  const togglePlayRef = useRef<() => void | Promise<void>>(() => {});
  useEffect(() => {
    togglePlayRef.current = togglePlay;
  }, [togglePlay]);
  useEffect(() => {
    if (!autoStart || isPlaying || isFinished) return;
    const id = setTimeout(() => {
      togglePlayRef.current?.();
    }, 200);
    return () => clearTimeout(id);
  }, [autoStart, isPlaying, isFinished]);

  const handleLevelChange = useCallback(
    (direction: number) => {
      const targetLevel = Math.min(MAX_LEVELS, Math.max(1, currentLevel + direction));
      resetGame();
      setCurrentLevel(targetLevel);
      setShuffledGrid([...(levelData[targetLevel] ?? defaultLevels[targetLevel])]);
    },
    [resetGame, currentLevel, levelData]
  );

  const handleWordEdit = useCallback((index: number, value: string) => {
    setLevelData((prev) => {
      const newWords = [...(prev[currentLevel] ?? defaultLevels[currentLevel])];
      newWords[index] = value;
      return { ...prev, [currentLevel]: newWords };
    });
  }, [currentLevel]);

  const handleBpmChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const index = parseInt(e.target.value, 10);
    const nextBpm = bpmOptions[index] ?? 100;
    bpmRef.current = getEffectiveBpm(nextBpm);
    setBpm(nextBpm);
  }, []);

  const triggerImageUpload = useCallback((index: number) => {
    setUploadTargetIndex(index);
    fileInputRef.current?.click();
  }, []);

  const handleFileChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file && uploadTargetIndex !== null) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const result = reader.result as string;
          setLevelData((prev) => {
            const newWords = [...(prev[currentLevel] ?? defaultLevels[currentLevel])];
            newWords[uploadTargetIndex] = result;
            return { ...prev, [currentLevel]: newWords };
          });
          setUploadTargetIndex(null);
          event.target.value = '';
        };
        reader.readAsDataURL(file);
      }
    },
    [uploadTargetIndex, currentLevel]
  );

  const clearCell = useCallback((index: number) => {
    setLevelData((prev) => {
      const newWords = [...(prev[currentLevel] ?? defaultLevels[currentLevel])];
      newWords[index] = '';
      return { ...prev, [currentLevel]: newWords };
    });
  }, [currentLevel]);

  const effectiveEditing = allowEdit && isEditing;
  const totalActionBeats = MAX_LEVELS * ROUNDS_PER_LEVEL * BEATS_PER_PHASE;
  const progressPercent = Math.min(100, (totalBeatsPlayed / totalActionBeats) * 100);
  const estimatedDuration = Math.round(
    getTotalChallengeDurationSec(bpm, bgmSourceBpm)
  ).toString();

  const isListenPhase = currentBeat >= 0 && currentBeat < 8;
  const isActionPhase = currentBeat >= 8;
  const displayBeat = isActionPhase ? currentBeat - 8 : currentBeat;

  const grid =
    shuffledGrid.length > 0
      ? shuffledGrid
      : (levelData[currentLevel] ?? defaultLevels[currentLevel]);

  return (
    <div
      className="min-h-screen font-sans flex flex-col items-center py-6 sm:py-10 px-3 sm:px-4 selection:bg-green-200 relative overflow-x-hidden overflow-y-auto"
      style={{
        backgroundColor: '#f4f1ea',
        backgroundImage: `url("data:image/svg+xml,%3Csvg width='200' height='200' viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100' height='100' filter='url(%23noise)' opacity='0.08'/%3E%3C/svg%3E")`,
      }}
    >
      {!isFinished && (
        <>
          <div
            className={`fixed top-4 left-4 md:top-8 md:left-8 z-0 transition-transform duration-100 ${
              isPlaying && !isCountingDown && !isTransitioning && isActionPhase && displayBeat % 2 === 0
                ? 'scale-110 -rotate-6'
                : 'scale-100'
            }`}
          >
            <div className="p-3 bg-white rounded-2xl shadow-md border-2 border-gray-900 text-green-600">
              <Megaphone size={28} strokeWidth={2.5} />
            </div>
          </div>
          <div
            className={`fixed top-4 right-4 md:top-8 md:right-8 z-0 transition-transform duration-100 ${
              isPlaying && !isCountingDown && !isTransitioning && isActionPhase && displayBeat % 2 !== 0
                ? 'scale-110 rotate-6'
                : 'scale-100'
            }`}
          >
            <div className="p-3 bg-white rounded-2xl shadow-md border-2 border-gray-900 text-yellow-500">
              <Lightbulb size={28} strokeWidth={2.5} />
            </div>
          </div>
          <div
            className={`fixed bottom-4 left-4 md:bottom-8 md:left-8 z-0 transition-transform duration-100 ${
              isPlaying && !isCountingDown && !isTransitioning && isActionPhase && displayBeat === 0
                ? 'scale-125 rotate-12 text-rose-500'
                : 'scale-100 text-rose-400'
            }`}
          >
            <div className="p-3 bg-white rounded-2xl shadow-md border-2 border-gray-900">
              <Zap
                size={28}
                strokeWidth={2.5}
                fill={
                  isPlaying && isActionPhase && displayBeat === 0 ? 'currentColor' : 'none'
                }
              />
            </div>
          </div>
          <div
            className={`fixed bottom-4 right-4 md:bottom-8 md:right-8 z-0 transition-transform duration-100 ${
              isPlaying && !isCountingDown && !isTransitioning && isActionPhase && displayBeat === 4
                ? 'scale-125 -rotate-12 text-indigo-500'
                : 'scale-100 text-indigo-400'
            }`}
          >
            <div className="p-3 bg-white rounded-2xl shadow-md border-2 border-gray-900">
              <AlertCircle size={28} strokeWidth={2.5} />
            </div>
          </div>
        </>
      )}

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        accept="image/*"
        className="hidden"
      />

      <style>
        {`
          @import url('https://fonts.googleapis.com/css2?family=Black+Han+Sans&family=Noto+Sans+KR:wght@400;700&family=Outfit:wght@300;600;800&display=swap');
          .font-outfit { font-family: 'Outfit', sans-serif; }
          .font-display { font-family: 'Black Han Sans', sans-serif; }
          .font-body { font-family: 'Noto Sans KR', sans-serif; }
        `}
      </style>

      {!isFinished && (
        <>
          <header className="w-full max-w-4xl flex flex-col items-center mb-8 z-10">
        <div className="flex items-center gap-3 mb-2 bg-white px-6 py-3 rounded-full border-2 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,1)]">
          <div className="p-1 bg-green-500 rounded-lg text-white border-2 border-black">
            <Music className="w-5 h-5" />
          </div>
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-outfit font-extrabold tracking-tighter text-gray-900">
            무빙 챌린지
          </h1>
        </div>
      </header>

      <div className="w-full max-w-3xl relative z-10">
        <div className="mb-6 px-2">
          <div className="flex justify-between items-end mb-3">
            <div className="flex items-center gap-4">
              <div className="flex flex-col">
                <span className="font-outfit text-xs text-gray-500 font-bold tracking-wider mb-1">
                  CURRENT LEVEL
                </span>
                <span className="font-outfit text-xl sm:text-2xl font-black bg-gray-900 text-white px-3 sm:px-4 py-1 rounded-lg shadow-md">
                  LEVEL 0{currentLevel} <span className="text-gray-300 font-bold text-sm">/ {MAX_LEVELS}</span>
                </span>
              </div>
              <div className="flex flex-col">
                <span className="font-outfit text-xs text-gray-500 font-bold tracking-wider mb-1">
                  PATTERN
                </span>
                <span className="font-outfit text-2xl font-black text-gray-800">
                  {roundInLevel}
                  <span className="text-gray-400 text-lg mx-1">/</span>
                  {ROUNDS_PER_LEVEL}
                </span>
              </div>
            </div>

            <div className="flex flex-wrap justify-center gap-1 sm:gap-2">
              {Array.from({ length: MAX_LEVELS }, (_, i) => i + 1).map((lv) => (
                <button
                  key={lv}
                  type="button"
                  onClick={() => handleLevelChange(lv - currentLevel)}
                  disabled={isPlaying || isTransitioning || currentLevel === lv}
                  className={`min-w-[2.25rem] sm:min-w-[2.5rem] h-9 sm:h-10 rounded-lg border-2 border-gray-900 font-black text-sm transition-all disabled:opacity-50 disabled:cursor-not-allowed touch-manipulation ${
                    currentLevel === lv
                      ? 'bg-green-500 text-white'
                      : 'bg-white text-gray-900 hover:bg-gray-100'
                  } shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] active:translate-y-[2px] active:shadow-none`}
                >
                  {lv}
                </button>
              ))}
            </div>

            <div className="flex-1 flex justify-center min-w-0">
              {isListenPhase && !isCountingDown && (
                <div className="flex items-center gap-2 bg-rose-100 text-rose-600 px-4 py-1 rounded-full border-2 border-rose-200 animate-pulse">
                  <Ear size={20} />
                  <span className="font-black font-outfit">LISTEN</span>
                </div>
              )}
              {isActionPhase && !isCountingDown && (
                <div className="flex items-center gap-2 bg-green-100 text-green-600 px-4 py-1 rounded-full border-2 border-green-200 animate-bounce">
                  <Mic size={20} />
                  <span className="font-black font-outfit">GO!</span>
                </div>
              )}
            </div>

            <div className="flex gap-2 flex-shrink-0">
              <button
                type="button"
                onClick={() => handleLevelChange(-1)}
                disabled={isPlaying || isTransitioning || currentLevel <= 1}
                className="w-10 h-10 rounded-lg border-2 border-gray-900 bg-white hover:bg-gray-100 text-gray-900 font-black flex items-center justify-center transition-all disabled:opacity-30 touch-manipulation shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] active:translate-y-[2px] active:shadow-none"
                aria-label="이전 레벨"
              >
                −
              </button>
              <button
                type="button"
                onClick={() => handleLevelChange(1)}
                disabled={isPlaying || isTransitioning || currentLevel >= MAX_LEVELS}
                className="w-10 h-10 rounded-lg border-2 border-gray-900 bg-white hover:bg-gray-100 text-gray-900 font-black flex items-center justify-center transition-all disabled:opacity-30 touch-manipulation shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] active:translate-y-[2px] active:shadow-none"
                aria-label="다음 레벨"
              >
                +
              </button>
            </div>
          </div>

          <div className="w-full h-4 bg-white border-2 border-gray-900 rounded-full overflow-hidden p-0.5">
            <div
              className="h-full bg-green-500 rounded-full transition-all duration-300 ease-linear border border-black"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>

        <div className="relative">
          {isTransitioning && (
            <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-white/95 backdrop-blur-md rounded-3xl border-4 border-gray-900 shadow-xl animate-in fade-in zoom-in duration-300">
              <span className="text-xl font-bold text-gray-500 tracking-widest mb-2 font-outfit">
                LEVEL {currentLevel} COMPLETE!
              </span>
              <span className="text-5xl font-black text-gray-900 mb-2 font-outfit">
                NEXT LEVEL {Math.min(currentLevel + 1, MAX_LEVELS)}
              </span>
              {restCountdown != null && (
                <span
                  className="text-[10rem] md:text-[12rem] font-black text-green-500 drop-shadow-[6px_6px_0px_rgba(0,0,0,1)] animate-pulse mt-4 font-outfit"
                  style={{ WebkitTextStroke: '3px black' }}
                >
                  {restCountdown}
                </span>
              )}
              {restCountdown == null && (
                <div className="flex gap-2 animate-bounce mt-6">
                  <ArrowRight size={32} className="text-green-500" />
                  <ArrowRight size={32} className="text-green-500 opacity-50" />
                  <ArrowRight size={32} className="text-green-500 opacity-25" />
                </div>
              )}
            </div>
          )}

          {currentBeat < 0 && isPlaying && !isTransitioning && !isFinishingRest && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center pointer-events-none">
              <span
                className="text-[10rem] md:text-[12rem] font-black text-green-500 drop-shadow-[6px_6px_0px_rgba(0,0,0,1)] animate-pulse"
                style={{ WebkitTextStroke: '3px black' }}
              >
                {Math.abs(currentBeat)}
              </span>
            </div>
          )}

          <div
            className={`grid grid-cols-4 gap-4 mb-8 relative transition-all duration-500 p-6 bg-white/90 rounded-3xl border-2 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,0.15)] ${
              isTransitioning ? 'opacity-0 scale-95' : 'opacity-100 scale-100'
            }`}
          >
            {grid.map((content, index) => {
              const isActive =
                !isCountingDown && !isTransitioning && currentBeat >= 0 && displayBeat === index;
              const hasImage = isImage(content);

              let borderClass =
                'border-2 border-gray-900 shadow-[4px_4px_0px_0px_rgba(0,0,0,0.15)]';
              if (isActive) {
                if (isListenPhase)
                  borderClass =
                    'border-[6px] border-rose-500 scale-105 z-10 shadow-[0_0_15px_rgba(244,63,94,0.4)]';
                if (isActionPhase)
                  borderClass =
                    'border-[6px] border-green-500 scale-105 z-10 shadow-[0_0_15px_rgba(34,197,94,0.4)]';
              }

              return (
                <div
                  key={`${gridLayoutKey}-${index}`}
                  className={`
                    aspect-square flex items-center justify-center rounded-xl transition-all duration-75 relative overflow-hidden bg-white
                    ${borderClass}
                  `}
                >
                  {hasImage ? (
                    <img
                      src={content}
                      alt=""
                      loading="eager"
                      decoding="async"
                      draggable={false}
                      className={`w-full h-full object-contain ${effectiveEditing ? 'opacity-50' : ''}`}
                    />
                  ) : effectiveEditing ? (
                    <input
                      type="text"
                      value={
                        composingCell?.index === index ? composingCell.value : content
                      }
                      onCompositionStart={(e) => {
                        setComposingCell({
                          index,
                          value: (e.target as HTMLInputElement).value,
                        });
                      }}
                      onCompositionEnd={(e) => {
                        const v = (e.target as HTMLInputElement).value;
                        handleWordEdit(index, v);
                        setComposingCell(null);
                      }}
                      onChange={(e) => {
                        const v = e.target.value;
                        if (composingCell?.index === index) {
                          setComposingCell((prev) => (prev ? { ...prev, value: v } : null));
                        } else {
                          handleWordEdit(index, v);
                        }
                      }}
                      onBlur={(e) => {
                        if (composingCell?.index === index) {
                          handleWordEdit(index, (e.target as HTMLInputElement).value);
                          setComposingCell(null);
                        }
                      }}
                      className="w-full h-full text-center bg-transparent text-gray-900 font-display text-3xl focus:outline-none placeholder-gray-300"
                      maxLength={3}
                      placeholder="입력"
                    />
                  ) : (
                    <span className="font-display text-4xl md:text-5xl select-none relative z-10 text-gray-900">
                      {content}
                    </span>
                  )}
                  {effectiveEditing && !isPlaying && (
                    <div className="absolute inset-0 pointer-events-none">
                      <div className="absolute top-1 right-1 flex gap-1 pointer-events-auto">
                        {hasImage ? (
                          <button
                            onClick={() => clearCell(index)}
                            className="p-1.5 bg-white rounded-md border-2 border-gray-900 text-red-500 hover:bg-red-50 shadow-sm"
                          >
                            <X size={14} strokeWidth={3} />
                          </button>
                        ) : (
                          <button
                            onClick={() => triggerImageUpload(index)}
                            className="p-1.5 bg-white rounded-md border-2 border-gray-900 text-gray-500 hover:text-green-600 shadow-sm"
                          >
                            <ImageIcon size={14} />
                          </button>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white border-2 border-gray-900 shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] rounded-2xl p-5 flex flex-col md:flex-row items-center gap-6 justify-between mb-8">
          <div className="flex items-center gap-4">
            <button
              type="button"
              onClick={togglePlay}
              disabled={isTransitioning}
              className={`
                w-14 h-14 sm:w-16 sm:h-16 rounded-full flex items-center justify-center shadow-lg transition-all hover:scale-105 active:scale-95 border-2 border-gray-900 touch-manipulation
                ${
                  isFinished
                    ? 'bg-gray-200 text-gray-500 cursor-pointer hover:bg-gray-300'
                    : isPlaying
                      ? 'bg-red-500 text-white'
                        : 'bg-green-500 text-white'
                  }
                  ${isTransitioning ? 'opacity-50 cursor-not-allowed' : ''}
                `}
              >
                {isFinished ? (
                  <RefreshCw size={28} />
                ) : isPlaying ? (
                  <Pause size={28} fill="currentColor" />
                ) : (
                  <Play size={28} fill="currentColor" className="ml-1" />
                )}
              </button>

            <button
              onClick={resetGame}
              className="w-12 h-12 rounded-full border-2 border-gray-900 bg-white flex items-center justify-center text-gray-500 hover:bg-gray-100 transition-colors shadow-sm"
            >
              <RefreshCw size={20} />
            </button>

            {onEnd && (
              <button
                type="button"
                onClick={onEnd}
                className="px-4 py-2 rounded-xl border-2 border-gray-900 bg-white text-gray-700 text-sm font-bold hover:bg-gray-50 shadow-[2px_2px_0px_0px_rgba(0,0,0,1)]"
              >
                Phase 종료
              </button>
            )}
          </div>

          <div className="flex items-center gap-4 w-full md:w-auto flex-1 md:max-w-xs bg-gray-50 p-3 rounded-xl border-2 border-gray-200 relative">
            {(isPlaying || lockBpm) && (
              <div className="absolute inset-0 bg-gray-100/50 z-20 cursor-not-allowed rounded-xl" />
            )}
            <div className="w-10 h-10 rounded-lg bg-white flex items-center justify-center border-2 border-gray-200">
              <Settings size={20} className="text-gray-400" />
            </div>
            <div className="flex-1 flex flex-col gap-1">
              <div className="flex justify-between items-center text-xs font-outfit font-bold text-gray-500">
                <span>SPEED</span>
                <span className="text-green-600">{bpm} BPM{lockBpm ? ' (고정)' : ''}</span>
              </div>
              {!lockBpm && (
                <div className="relative flex items-center">
                  <div className="absolute w-full flex justify-between px-1 -bottom-3 pointer-events-none">
                    {bpmOptions.map((opt) => (
                      <div
                        key={opt}
                        className={`w-1 h-1 rounded-full ${bpm === opt ? 'bg-green-500' : 'bg-gray-300'}`}
                      />
                    ))}
                  </div>
                  <input
                    type="range"
                    min={0}
                    max={bpmOptions.length - 1}
                    step={1}
                    value={bpmOptions.indexOf(bpm)}
                    onChange={handleBpmChange}
                    className="w-full h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-green-500 z-10"
                  />
                </div>
              )}
            </div>
          </div>

          {allowEdit && (
            <button
              onClick={() => setIsEditing(!isEditing)}
              disabled={isPlaying || isTransitioning}
              className={`
                flex items-center gap-2 px-5 py-3 rounded-xl font-body font-bold text-sm transition-all shadow-[2px_2px_0px_0px_rgba(0,0,0,1)] border-2 border-gray-900 active:translate-y-[2px] active:shadow-none
                ${
                  isEditing
                    ? 'bg-green-100 text-green-800'
                    : 'bg-white text-gray-700 hover:bg-gray-50'
                }
                disabled:opacity-50 disabled:cursor-not-allowed
              `}
            >
              {isEditing ? (
                <Check size={18} strokeWidth={3} />
              ) : (
                <Edit3 size={18} />
              )}
              <span className="hidden md:inline">{isEditing ? '완료' : '수정'}</span>
            </button>
          )}

          {allowEdit && onPresetChange && (
            <button
              type="button"
              onClick={() => {
                const gridsByLevel: Record<number, string[]> = {
                  1: (levelData[1] ?? defaultLevels[1]).slice(0, 8),
                  2: (levelData[2] ?? defaultLevels[2]).slice(0, 8),
                  3: (levelData[3] ?? defaultLevels[3]).slice(0, 8),
                  4: (levelData[4] ?? defaultLevels[4]).slice(0, 8),
                };
                onPresetChange({
                  bpm,
                  level: currentLevel,
                  grid: (levelData[currentLevel] ?? defaultLevels[currentLevel]).slice(0, 8),
                  gridsByLevel,
                });
              }}
              disabled={isPlaying}
              className="flex items-center gap-2 px-4 py-2 rounded-xl font-body font-bold text-sm bg-amber-500/20 text-amber-700 border-2 border-amber-400/50 hover:bg-amber-500/30 disabled:opacity-50 disabled:cursor-not-allowed shadow-[2px_2px_0px_0px_rgba(0,0,0,0.3)]"
            >
              픽스
            </button>
          )}
        </div>
      </div>
        </>
      )}

      {isFinished && (
        <div className="w-full max-w-3xl relative z-10 px-2">
          <div className="w-full bg-white border-2 border-gray-900 rounded-3xl p-8 shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] animate-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-3 bg-green-100 rounded-full text-green-600 border-2 border-gray-900">
                <Zap size={28} fill="currentColor" />
              </div>
              <h3 className="text-3xl font-black text-gray-900 font-outfit">Excellent!</h3>
            </div>
            <div className="space-y-3 text-gray-600 font-body leading-relaxed text-lg">
              <p>
                총{' '}
                <strong className="text-green-600 bg-green-50 px-1 rounded">
                  {MAX_LEVELS}단계({estimatedDuration}초)
                </strong>{' '}
                챌린지를 완주했어요!
              </p>
              <ul className="text-base list-disc list-inside space-y-1">
                <li>듣고 따라하며(Listen & Speak) 언어 감각이 발달했습니다.</li>
                <li>정확한 타이밍에 반응하며 리듬감이 향상되었습니다.</li>
              </ul>
            </div>
            <button
              onClick={resetGame}
              className="mt-8 w-full py-4 bg-green-500 text-white font-black text-lg rounded-xl hover:bg-green-600 transition-colors shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] border-2 border-black active:translate-y-[4px] active:shadow-none"
            >
              다시 도전하기 (RESTART)
            </button>
          </div>
        </div>
      )}

      <div className="mt-16 max-w-3xl w-full grid grid-cols-1 md:grid-cols-3 gap-6 opacity-60">
        <div className="text-center">
          <p className="font-outfit font-bold text-gray-400 text-sm tracking-widest uppercase">
            PLAY → THINK → FLOW
          </p>
        </div>
      </div>
    </div>
  );
}

export default function CurriculumLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <>
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link
        rel="preconnect"
        href="https://fonts.gstatic.com"
        crossOrigin="anonymous"
      />
      <link
        href="https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;1,9..40,300&display=swap"
        rel="stylesheet"
      />
      <link
        href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.css"
        rel="stylesheet"
      />
      {children}
    </>
  );
}

'use client';

import { useCallback, useState } from 'react';
import Link from 'next/link';

const NAV_LINKS = [
  { href: '#instructors', label: '소개' },
  { href: '#curriculum', label: '커리큘럼' },
  { href: '#class-flow', label: '수업 현장' },
  { href: '#move-report', label: 'Move report' },
  { href: '#reviews', label: '후기' },
];

function ShieldIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
    </svg>
  );
}

function MenuIcon() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M4 6h16M4 12h16M4 18h16" />
    </svg>
  );
}

function CloseIcon() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M18 6L6 18M6 6l12 12" />
    </svg>
  );
}

export default function Header() {
  const [drawerOpen, setDrawerOpen] = useState(false);

  const closeDrawer = useCallback(() => setDrawerOpen(false), []);

  return (
    <>
      <div
        className={`pl-drawer-backdrop ${drawerOpen ? 'show' : ''}`}
        aria-hidden={!drawerOpen}
        onClick={closeDrawer}
        role="presentation"
      />
      <aside
        className={`pl-drawer ${drawerOpen ? 'open' : ''}`}
        aria-hidden={!drawerOpen}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Link href="#top" className="pl-brand" onClick={closeDrawer}>
            <div className="pl-brand-logo">S</div>
            SPOKEDU
          </Link>
          <button
            type="button"
            className="pl-burger"
            onClick={closeDrawer}
            aria-label="메뉴 닫기"
            style={{ display: 'flex' }}
          >
            <CloseIcon />
          </button>
        </div>
        <div className="pl-drawer-links">
          {NAV_LINKS.map(({ href, label }) => (
            <Link key={href} href={href} onClick={closeDrawer}>
              {label}
            </Link>
          ))}
          <Link href="#apply" onClick={closeDrawer}>
            상담 접수
          </Link>
          <a href="tel:010-4437-9294" onClick={closeDrawer}>
            유선 문의
          </a>
        </div>
