/* ── 저장 모달 ──────────────────────────────────────────── */

.spm-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(4,5,9,0.72);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 12px 24px;
  animation: spm-backdrop-in 0.2s ease both;
}

@keyframes spm-backdrop-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.spm-modal {
  width: 100%;
  max-width: 492px;
  padding: 28px 24px 24px;
  border: 1px solid var(--line-2);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(22,25,36,0.98) 0%, rgba(13,15,22,0.98) 100%);
  box-shadow: 0 -4px 40px rgba(0,0,0,0.4);
  animation: spm-modal-up 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes spm-modal-up {
  from { transform: translateY(32px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}

.spm-modal-title {
  font-family: 'Outfit', 'Pretendard', sans-serif;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.spm-modal-sub {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-2);
  margin-bottom: 20px;
  line-height: 1.5;
}

.spm-modal-input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid var(--line-2);
  border-radius: 14px;
  background: rgba(255,255,255,0.05);
  color: var(--text);
  font-size: 15px;
  font-weight: 600;
  outline: none;
  margin-bottom: 16px;
  transition: border-color 0.18s ease;
}

.spm-modal-input:focus {
  border-color: var(--accent-line);
}

.spm-modal-input::placeholder {
  color: var(--text-3);
  font-weight: 500;
}

.spm-modal-row {
  display: flex;
  gap: 10px;
}

.spm-modal-cancel {
  flex: 1;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255,255,255,0.04);
  color: var(--text-2);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: border-color 0.18s ease, color 0.18s ease;
}

.spm-modal-cancel:hover {
  border-color: var(--line-3);
  color: var(--text);
}

.spm-modal-save {
  flex: 2;
  padding: 14px;
  border: none;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  color: #0B0D0A;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  box-shadow: 0 10px 20px rgba(200,255,0,0.14);
}

.spm-modal-save:hover {
  transform: translateY(-1px);
}

.spm-modal-save:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* ── 4단계 풋터 별 버튼 ─────────────────────────────────── */

.spm-btn-star {
