  const [durMode, setDurMode] = useState('round');
  const [cdTime, setCdTime] = useState(60);
  const [rounds, setRounds] = useState(10);
  const [sets, setSets] = useState(3);

  const [curSet, setCurSet] = useState(1);
  const [curRound, setCurRound] = useState(0);
  const [timeLeft, setTimeLeft] = useState(0);
  const [stimulus, setStimulus] = useState<Stimulus | null>(null);
  const [visible, setVisible] = useState(false);
  const [totalR, setTotalR] = useState(0);

  const sessionRef = useRef({ curRound, rounds, durMode, curSet, sets });
  sessionRef.current = { curRound, rounds, durMode, curSet, sets };

  const pendingTimeoutsRef = useRef<number[]>([]);
  const touchCooldownRef = useRef(false);
  const lastStimulusRef = useRef<Stimulus | null>(null);

  const queueTimeout = useCallback((callback: () => void, delay: number) => {
    const id = window.setTimeout(() => {
      pendingTimeoutsRef.current = pendingTimeoutsRef.current.filter((t) => t !== id);
      callback();
    }, delay);
    pendingTimeoutsRef.current.push(id);
    return id;
  }, []);

  const clearPendingTimeouts = useCallback(() => {
    pendingTimeoutsRef.current.forEach((id) => window.clearTimeout(id));
    pendingTimeoutsRef.current = [];
  }, []);

  useEffect(() => {
    return () => clearPendingTimeouts();
  }, [clearPendingTimeouts]);

  const validStepOne = selColors.length > 0 || selArrows.length > 0 || selNums.length > 0;
  const compoundAvailable = selColors.length > 0 && (selArrows.length > 0 || selNums.length > 0);

  const generateStimulus = useCallback((): Stimulus | null => {
    const hasColors = selColors.length > 0;
    const hasArrows = selArrows.length > 0;
    const hasNumbers = selNums.length > 0;

    if (!hasColors && !hasArrows && !hasNumbers) return null;

    const generateOnce = (): Stimulus => {
      if (stroop && hasColors && (hasArrows || hasNumbers)) {
        const fgPool: ('arrow' | 'number')[] = [
          ...(hasArrows ? (['arrow'] as const) : []),
          ...(hasNumbers ? (['number'] as const) : []),
        ];
        const fgType = pickRandom(fgPool);
        return {
          type: 'stroop',
          colorVal: pickRandom(selColors),
          fgType,
          fgVal: fgType === 'arrow' ? pickRandom(selArrows) : pickRandom(selNums),
        };
      }

      const typePool = [
        ...(hasColors ? ['color'] : []),
        ...(hasArrows ? ['arrow'] : []),
        ...(hasNumbers ? ['number'] : []),
      ];
      const type = pickRandom(typePool);

      if (type === 'color') return { type: 'color', val: pickRandom(selColors) };
      if (type === 'arrow') return { type: 'arrow', val: pickRandom(selArrows) };
      return { type: 'number', val: pickRandom(selNums) };
    };

    const candidate = generateOnce();
    // 직전 자극과 동일하면 한 번 재추첨 → 연속 중복 확률 약 50% 감소
    if (stimuliEqual(candidate, lastStimulusRef.current)) {
      return generateOnce();
    }
    return candidate;
  }, [selColors, selArrows, selNums, stroop]);

  const resetToSettings = useCallback(() => {
    clearPendingTimeouts();
    setStimulus(null);
    setVisible(false);
    setScreen('intro');
    setStep(1);
  }, [clearPendingTimeouts]);

  const endSet = useCallback(() => {
    const { curSet: cs, sets: ts } = sessionRef.current;
    setVisible(false);
    setStimulus(null);
    setScreen(cs >= ts ? 'result' : 'break');
  }, []);

  const advanceRef = useRef<(() => void) | null>(null);
  advanceRef.current = () => {
    const { curRound: cr, rounds: tr, durMode: dm } = sessionRef.current;
    if (dm === 'round' && cr >= tr) {
      endSet();
      return;
    }
    const newStim = generateStimulus();
    lastStimulusRef.current = newStim;
    setStimulus(newStim);
    setVisible(true);
    if (dm === 'round') {
      setCurRound((p) => p + 1);
      setTotalR((p) => p + 1);
    }
  };

  useEffect(() => {
    if (screen !== 'game' || trans !== 'time') return;
    const { durMode: dm, curRound: cr, rounds: tr } = sessionRef.current;
    let id: number;
    if (visible) {
      id = window.setTimeout(() => {
        setVisible(false);
        if (dm === 'round' && cr >= tr) endSet();
      }, dispT * 1000);
    } else {
      id = window.setTimeout(() => advanceRef.current?.(), blankT * 1000);
    }
    return () => window.clearTimeout(id);
  }, [screen, trans, visible, dispT, blankT, endSet]);

  useEffect(() => {
    if (screen !== 'game' || durMode !== 'countdown') return;
    const id = window.setInterval(() => {
      setTimeLeft((p) => {
        if (p <= 1) {
          window.clearInterval(id);
          endSet();
          return 0;
        }
        return p - 1;
      });
    }, 1000);
    return () => window.clearInterval(id);
  }, [screen, durMode, endSet]);

  const handleTouch = useCallback(() => {
    if (trans !== 'touch' || screen !== 'game' || touchCooldownRef.current) return;
    touchCooldownRef.current = true;
    clearPendingTimeouts();
    queueTimeout(() => { touchCooldownRef.current = false; }, 80);
    setVisible(false);
    queueTimeout(() => advanceRef.current?.(), 55);
  }, [trans, screen, clearPendingTimeouts, queueTimeout]);

  const startGame = useCallback(() => {
    clearPendingTimeouts();
    setCurSet(1);
    setCurRound(0);
    setTotalR(0);
    setStimulus(null);
    setVisible(false);
    setTimeLeft(durMode === 'countdown' ? cdTime : 0);
    lastStimulusRef.current = null;
    setScreen('countdown');
  }, [clearPendingTimeouts, durMode, cdTime]);

  const startSet = useCallback((nextSet: number) => {
    clearPendingTimeouts();
    setCurSet(nextSet);
    setCurRound(0);
    setStimulus(null);
    setVisible(false);
    setTimeLeft(durMode === 'countdown' ? cdTime : 0);
    lastStimulusRef.current = null;
    setScreen('countdown');
  }, [clearPendingTimeouts, durMode, cdTime]);

  const handleCountdownDone = useCallback(() => {
    setScreen('game');
    queueTimeout(() => advanceRef.current?.(), 50);
  }, [queueTimeout]);

  const showToast = useCallback((msg: string, ok: boolean) => {
    if (toastTimerRef.current) window.clearTimeout(toastTimerRef.current);
    setToast({ msg, ok });
    toastTimerRef.current = window.setTimeout(() => setToast(null), 2600);
  }, []);

  const hydrateFromFavorite = useCallback((payload: SpmPayload) => {
    setSelColors(sanitizeColorIds(payload.selColors));
    setSelArrows(payload.selArrows);
    setSelNums(payload.selNums);
    setStroop(payload.stroop);
    setTrans(payload.trans);
    setDispT(payload.dispT);
    setBlankT(payload.blankT);
    setDurMode(payload.durMode);
    setCdTime(payload.cdTime);
    setRounds(payload.rounds);
    setSets(payload.sets);
    setStep(4);
    setScreen('settings');
  }, []);

  const handleSaveFavorite = useCallback(async () => {
    setSaving(true);
    const payload: SpmPayload = {
      selColors, selArrows, selNums, stroop,
      trans: trans as 'touch' | 'time',
      dispT, blankT,
      durMode: durMode as 'round' | 'countdown',
      cdTime, rounds, sets,
    };
    try {
      const res = await fetch('/api/teacher/spomove/favorites', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ label: saveLabel.trim() || '이름 없음', payload }),
      });
      const json = await res.json();
      if (!json.ok) {
        showToast(json.message ?? json.error ?? '저장 실패', false);
      } else {
        showToast('즐겨찾기에 저장되었습니다.', true);
        setSaveModalOpen(false);
        setSaveLabel('');
      }
    } catch {
      showToast('네트워크 오류가 발생했습니다.', false);
    } finally {
      setSaving(false);
    }
  }, [selColors, selArrows, selNums, stroop, trans, dispT, blankT, durMode, cdTime, rounds, sets, saveLabel, showToast]);

  const summary = useMemo(() => ([
    {
      k: '자극 유형',
      v: [
        selColors.length > 0 && '색깔',
        selArrows.length > 0 && '화살표',
        selNums.length > 0 && '숫자',
      ].filter(Boolean).join(' / ') || '—',
    },
    ...(stroop ? [{ k: '복합 자극', v: 'ON', a: true }] : []),
    { k: '전환 방식', v: trans === 'touch' ? 'TOUCH' : 'AUTO' },
    { k: '타임라인', v: durMode === 'countdown' ? formatTime(cdTime) : `${rounds} RND` },
    { k: '세트', v: `${sets} SET` },
  ]), [selColors.length, selArrows.length, selNums.length, stroop, trans, durMode, cdTime, rounds, sets]);

  const gameVisual = useMemo(() => {
    if (!visible || !stimulus) return { visualStyle: DEFAULT_GAME_BG, content: null };

    if (stimulus.type === 'stroop') {
      const bg = getColorHex(stimulus.colorVal);
      if (stimulus.fgType === 'arrow') {
        const arrow = getArrowMeta(stimulus.fgVal as string);
        return {
          visualStyle: bg,
          content: (
            <div className="spm-s-arr-shell">
              <ArrowGlyph className="spm-s-arr" angle={arrow.angle} color="#070708" size={300} strokeWidth={8.5} />
            </div>
          ),
        };
      }
      const isYellow = stimulus.colorVal === 'yellow';
      return {
        visualStyle: bg,
        content: (
          <span className="spm-s-num" style={{ color: isYellow ? '#101114' : 'rgba(255,255,255,0.96)' }}>
            {stimulus.fgVal}
          </span>
        ),
      };
    }

    if (stimulus.type === 'color') return { visualStyle: getColorHex(stimulus.val), content: null };

    if (stimulus.type === 'arrow') {
      const arrow = getArrowMeta(stimulus.val);
      return {
        visualStyle: ARROW_ONLY_BG,
        content: (
          <div className="spm-s-arr-shell">
            <ArrowGlyph className="spm-s-arr" angle={arrow.angle} color="#070708" size={300} strokeWidth={8.5} />
          </div>
        ),
      };
    }

    return {
      visualStyle: NUMBER_BG,
      content: <span className="spm-s-num">{stimulus.val}</span>,
    };
  }, [visible, stimulus]);

  if (screen === 'intro') {
    return (
      <IntroScreen
        onCreate={() => {
          // Create 진입 시 이전 세션/즐겨찾기 상태를 비워 항상 현재 기본 옵션(4색) 기준으로 시작
          setSelColors([]);
          setSelArrows([]);
          setSelNums([]);
          setStroop(false);
          setTrans('touch');
          setDispT(1.0);
          setBlankT(0.5);
          setDurMode('round');
          setCdTime(60);
          setRounds(10);
          setSets(3);
          setStep(1);
          setTab('basic');
          setScreen('settings');
        }}
        onFavorite={() => setScreen('favoriteList')}
        onSpomove={() => setScreen('weekList')}
      />
    );
  }

  if (screen === 'favoriteList') {
    return (
      <FavoriteListScreen
        onBack={() => setScreen('intro')}
        onSelect={hydrateFromFavorite}
      />
    );
  }

  if (screen === 'weekList') {
    return (
      <WeekListScreen
        onBack={() => setScreen('intro')}
        onSelectWeek={(week) => {
          setSelectedWeek(week);
          setScreen('weekPrograms');
        }}
      />
    );
  }

  if (screen === 'weekPrograms' && selectedWeek != null) {
    return (
      <WeekProgramListScreen
        week={selectedWeek}
        onBack={() => setScreen('weekList')}
        onSelect={(program) => {
          setSelectedProgram(program);
          setPresetResult(null);
          setRunKey((k) => k + 1);
          setScreen('presetRunner');
        }}
      />
    );
  }

  if (screen === 'presetRunner' && selectedProgram) {
    return (
      <PresetRunnerScreen
        program={selectedProgram}
        runKey={runKey}
        onExit={() => setScreen('weekPrograms')}
        onComplete={(result) => {
          setPresetResult(result);
          setScreen('presetComplete');
        }}
      />
    );
  }

  if (screen === 'presetComplete' && selectedProgram && presetResult) {
    if (typeof document === 'undefined') return null;
    return createPortal(
      <TrainingResultScreen
        cfg={presetResult.cfg}
        elapsedMs={presetResult.elapsedMs}
        colorCounts={presetResult.colorCounts}
        levelLabel={resultLevelLabel(selectedProgram.mode, selectedProgram.level)}
        programTitle={selectedProgram.title}
        onBack={() => {
          setPresetResult(null);
          setScreen('weekPrograms');
        }}
        onRetry={() => {
          lockViewportScroll();
          setRunKey((k) => k + 1);
          setPresetResult(null);
          setScreen('presetRunner');
        }}
      />,
      document.body,
    );
  }

  if (screen === 'countdown') {
    return <CountdownScreen onDone={handleCountdownDone} />;
  }

  if (screen === 'game') {
    return (
      <GameScreen
        trans={trans}
        curSet={curSet}
        sets={sets}
        durMode={durMode}
        timeLeft={timeLeft}
        curRound={curRound}
        rounds={rounds}
        visualStyle={gameVisual.visualStyle}
        content={gameVisual.content}
        onTouch={handleTouch}
        onQuit={resetToSettings}
      />
    );
  }

  if (screen === 'break') {
    return <BreakScreen curSet={curSet} onStartNext={() => startSet(curSet + 1)} />;
  }

  if (screen === 'result') {
    return <ResultScreen sets={sets} durMode={durMode} totalR={totalR} onReset={resetToSettings} />;
  }

  return (
    <ScreenShell>
      <div className="spm-page">
        <TopBar step={step} />
        <StepHead step={step as 1 | 2 | 3 | 4} />

        {step === 1 && (
          <>
            <div className="spm-tab-row">
              <button className={`spm-tab-btn ${tab === 'basic' ? 'on' : ''}`} onClick={() => setTab('basic')}>
                기본
              </button>
              <button className={`spm-tab-btn ${tab === 'advanced' ? 'on' : ''}`} onClick={() => setTab('advanced')}>
                심화
              </button>
            </div>

            {tab === 'basic' && (
              <>
                <Block label="색깔">
                  <div className="spm-color-strip">
                    {COLOR_OPTIONS.map((color) => (
                      <button
                        key={color.id}
                        className={`spm-csw ${selColors.includes(color.id) ? 'on' : ''}`}
                        style={{ background: color.hex }}
                        onClick={() => setSelColors((p) => toggleInList(p, color.id))}
                        aria-label={color.label}
                        title={color.label}
                      />
                    ))}
                  </div>
                </Block>

                <Block label="화살표 — 8방향">
                  <div className="spm-grid4">
                    {ARROW_OPTIONS.map((arrow) => (
                      <button
                        key={arrow.id}
                        className={`spm-sym ${selArrows.includes(arrow.id) ? 'on' : ''}`}
                        onClick={() => setSelArrows((p) => toggleInList(p, arrow.id))}
                        aria-label={arrow.label}
                        title={arrow.label}
                      >
                        <ArrowGlyph className="spm-arrow-tile-icon" angle={arrow.angle} color="currentColor" strokeWidth={5.6} />
                      </button>
                    ))}
                  </div>
                </Block>

                <Block label="숫자 — 1 to 10">
                  <div className="spm-grid5">
                    {NUMBER_OPTIONS.map((number) => (
                      <button
                        key={number}
                        className={`spm-sym mono ${selNums.includes(number) ? 'on' : ''}`}
                        onClick={() => setSelNums((p) => toggleInList(p, number))}
                      >
                        {number}
                      </button>
                    ))}
                  </div>
                </Block>
              </>
            )}

            {tab === 'advanced' && (
              <Block label="복합 자극">
                <div className="spm-tog-row" onClick={() => setStroop((p) => !p)}>
                  <div className="spm-tog-text">
                    <h4>Compound stimulus</h4>
                    <p>색상 배경 위에 화살표 또는 숫자를 동시에 표시합니다. 색깔과 다른 자극이 함께 선택된 경우에만 실제로 작동합니다.</p>
                  </div>
                  <div className={`spm-sw ${stroop ? 'on' : ''}`}>
                    <div className="spm-sw-k" />
                  </div>
                </div>
                {stroop && !compoundAvailable && (
                  <div className="spm-tog-hint">Active — 기본 탭에서 색깔과 화살표 또는 숫자를 함께 선택해야 표시됩니다.</div>
                )}
                {stroop && compoundAvailable && (
                  <div className="spm-tog-hint">Active — 현재 조합으로 복합 자극이 정상 동작합니다.</div>
                )}
              </Block>
            )}
          </>
        )}

        {step === 2 && (
          <>
            <Block label="전환 방식">
              <div className="spm-opt-grid">
                <button className={`spm-opt ${trans === 'touch' ? 'on' : ''}`} onClick={() => setTrans('touch')}>
                  <h4>Touch</h4>
                  <p>화면 터치 시 다음 자극으로 전환됩니다.</p>
                </button>
                <button className={`spm-opt ${trans === 'time' ? 'on' : ''}`} onClick={() => setTrans('time')}>
                  <h4>Time</h4>
                  <p>지정한 시간 간격으로 자동 전환됩니다.</p>
                </button>
              </div>
            </Block>

            {trans === 'time' && (
              <Block label="시간 설정">
                <div className="spm-sl-stack">
                  <div>
                    <div className="spm-sl-meta">
                      <span className="spm-sl-name">노출 시간</span>
                      <span className="spm-sl-val">{dispT.toFixed(1)}s</span>
                    </div>
                    <input
                      type="range"
                      className="spm-range"
                      min="0" max="5" step="0.5"
                      value={dispT}
                      onChange={(e) => setDispT(parseFloat(e.target.value))}
                    />
                  </div>
                  <div>
                    <div className="spm-sl-meta">
                      <span className="spm-sl-name">공백 시간</span>
                      <span className="spm-sl-val">{blankT.toFixed(1)}s</span>
                    </div>
                    <input
                      type="range"
                      className="spm-range"
                      min="0" max="5" step="0.5"
                      value={blankT}
                      onChange={(e) => setBlankT(parseFloat(e.target.value))}
                    />
                  </div>
                </div>
              </Block>
            )}
          </>
        )}

        {step === 3 && (
          <>
            <Block label="기준">
              <div className="spm-opt-grid">
                <button className={`spm-opt ${durMode === 'countdown' ? 'on' : ''}`} onClick={() => setDurMode('countdown')}>
                  <h4>Countdown</h4>
                  <p>제한 시간 동안 진행합니다.</p>
                </button>
                <button className={`spm-opt ${durMode === 'round' ? 'on' : ''}`} onClick={() => setDurMode('round')}>
                  <h4>Rounds</h4>
                  <p>정해진 횟수만큼 반복합니다.</p>
                </button>
              </div>
            </Block>

            <Block label={durMode === 'countdown' ? '제한 시간' : '라운드 수'}>
              {durMode === 'countdown' ? (
                <div className="spm-pills">
                  {TIME_OPTIONS.map((t) => (
                    <button
                      key={t.value}
                      className={`spm-pill ${cdTime === t.value ? 'on' : ''}`}
                      onClick={() => setCdTime(t.value)}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              ) : (
                <>
                  <div className="spm-sl-meta">
                    <span className="spm-sl-name">목표 횟수</span>
                    <span className="spm-sl-val">{rounds}</span>
                  </div>
                  <input
                    type="range"
                    className="spm-range"
                    min="5" max="20" step="1"
                    value={rounds}
                    onChange={(e) => setRounds(parseInt(e.target.value, 10))}
                  />
                </>
              )}
            </Block>
          </>
        )}

        {step === 4 && (
          <>
            <Block label="총 세트 수">
              <div className="spm-set-big">
                <span className="spm-set-n">{sets}</span>
                <span className="spm-set-unit">sets</span>
              </div>
              <input
                type="range"
                className="spm-range"
                min="1" max="5" step="1"
                value={sets}
                onChange={(e) => setSets(parseInt(e.target.value, 10))}
              />
            </Block>

            <Block label="세션 요약">
              <div className="spm-sum-list">
                {summary.map((row) => (
                  <div key={row.k} className="spm-sum-row">
                    <span className="spm-sum-k">{row.k}</span>
                    <span className={row.a ? 'spm-sum-va' : 'spm-sum-v'}>{row.v}</span>
                  </div>
                ))}
              </div>
            </Block>
          </>
        )}

        <div className="spm-foot">
          {step > 1 ? (
            <button className="spm-btn-back" onClick={() => setStep((p) => p - 1)}>
              {L} back
            </button>
          ) : (
            <span />
          )}

          {step < 4 ? (
            <button
              className="spm-btn-next"
              disabled={step === 1 && !validStepOne}
              onClick={() => setStep((p) => p + 1)}
            >
              next {R}
            </button>
          ) : (
            <>
              <button
                className="spm-btn-star"
                onClick={() => { setSaveLabel(''); setSaveModalOpen(true); }}
                title="즐겨찾기에 저장"
                aria-label="즐겨찾기에 저장"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
                </svg>
                저장
              </button>
              <button className="spm-btn-next" onClick={startGame}>
                Start {PlayIco}
              </button>
            </>
          )}
        </div>
      </div>

      {/* 저장 모달 */}
      {saveModalOpen && (
        <div className="spm-modal-backdrop" onClick={() => setSaveModalOpen(false)}>
          <div className="spm-modal" onClick={(e) => e.stopPropagation()}>
            <div className="spm-modal-title">즐겨찾기 저장</div>
            <div className="spm-modal-sub">이 설정에 이름을 붙여 저장합니다.<br />같은 네트워크에서 최대 10개까지 가능합니다.</div>
            <input
              className="spm-modal-input"
              placeholder="이름 없음"
              value={saveLabel}
              maxLength={60}
              onChange={(e) => setSaveLabel(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !saving) handleSaveFavorite(); }}
              autoFocus
            />
            <div className="spm-modal-row">
              <button className="spm-modal-cancel" onClick={() => setSaveModalOpen(false)}>취소</button>
              <button className="spm-modal-save" onClick={handleSaveFavorite} disabled={saving}>
                {saving ? '저장 중…' : '저장'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 인라인 토스트 */}
      {toast && (
        <div className={`spm-toast ${toast.ok ? 'ok' : 'err'}`}>
          {toast.msg}
        </div>
      )}
    </ScreenShell>
  );
}

/**
 * Phase 1–2 회귀 QA (Playwright + API)
 *
 * Usage:
 *   node scripts/admin-note-regression-qa.mjs http://localhost:3000
 */
import nextEnv from '@next/env';
import {
  NOTE_QA_DOCUMENTS,
  createNoteQaContext,
  loadPlaywrightChromium,
  runCheck,
} from './note-qa/shared.mjs';
import { cleanupEphemeralQaDocumentsBestEffort } from './note-qa/cleanupEphemeralDocs.mjs';

const { loadEnvConfig } = nextEnv;
loadEnvConfig(process.cwd());

const BASE = (process.argv[2] || 'http://localhost:3000').replace(/\/$/, '');
const COMMON_BOARD_ID = NOTE_QA_DOCUMENTS[0]?.id ?? '7c095438-335b-4318-a3fb-09145f01d24a';
const JIHOON_NOTE_ID = '630e1104-84f9-41a2-b25b-7c4faa6a1300';
const GYM_TOGGLE_TITLE = '체육관 이용방법';
const RECONCILE_WAIT_MS = 3500;
const ZOMBIE_MARKER = '좀비회귀QA마커';
const REGRESSION_CLEANUP_OPTIONS = {
  titlePrefixes: ['Regression QA ', 'Toggle KB QA ', 'Toggle Zombie QA '],
};

function matchesGymToggleTitle(value) {
  return typeof value === 'string' && value.includes(GYM_TOGGLE_TITLE);
}

async function openDocument(page, documentId) {
  await page.goto(
    `${BASE}/admin/note?id=${encodeURIComponent(documentId)}`,
    { waitUntil: 'domcontentloaded' },
  );
  await page.waitForLoadState('networkidle').catch(() => undefined);
  await page.getByRole('status', { name: '페이지 불러오는 중' }).waitFor({ state: 'detached', timeout: 45000 }).catch(() => undefined);
  await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 45000 });
  await page.waitForTimeout(2000);
}

async function fetchBlocks(page, documentId, { skipServerMigration = false } = {}) {
  return page.evaluate(async ({ docId, skip }) => {
    const params = new URLSearchParams({ documentId: docId });
    if (skip) params.set('skipReconcile', 'true');
    const res = await fetch(`/api/admin/note/blocks/load?${params}`, { credentials: 'include' });
    if (!res.ok) throw new Error(`blocks/load ${res.status}`);
    const json = await res.json();
    return json.blocks ?? [];
  }, { docId: documentId, skip: skipServerMigration });
}

async function findToggleWithGymTitle(page, documentId) {
  const blocks = await fetchBlocks(page, documentId);
  const toggle = blocks.find((block) => {
    if (block.type !== 'toggle') return false;
    const title = block.content?.title;
    const text = block.content?.text;
    return matchesGymToggleTitle(title) || matchesGymToggleTitle(text);
  });
  if (!toggle) {
    const titles = blocks
      .filter((b) => b.type === 'toggle')
      .map((b) => (b.content?.title ?? b.content?.text ?? '').toString().trim())
      .filter(Boolean);
    throw new Error(`toggle "${GYM_TOGGLE_TITLE}" not found. toggles: ${titles.join(' | ') || '(none)'}`);
  }
  const children = blocks.filter((b) => b.parent_block_id === toggle.id);
  const legacyBody = [
    toggle.content?.body,
    toggle.content?.legacyBody,
    toggle.content?.bodyHtml,
    toggle.content?.legacyBodyHtml,
  ].filter((v) => typeof v === 'string' && v.trim()).join(' ');
  const childText = children
    .map((c) => (typeof c.content?.text === 'string' ? c.content.text : ''))
    .join(' ')
    .trim();
  return { toggle, children, legacyBody, childText };
}

async function expandToggleByTitleInDomAndRead(page, titleNeedle) {
  return page.evaluate(async (needle) => {
    const inputs = [...document.querySelectorAll('[data-toggle-title]')];
    const input = inputs.find((el) => (el.value || '').includes(needle));
    if (!input) return { ok: false, reason: 'input-not-found', childRowCount: 0, visibleText: '' };
    input.scrollIntoView({ block: 'center' });
    const toggleRoot = input.closest('.relative.overflow-visible.py-0\\.5')
      ?? input.parentElement?.parentElement;
    const button = toggleRoot?.querySelector('button[aria-label]');
    if (button?.getAttribute('aria-label') === '펼치기') {
      button.click();
      await new Promise((resolve) => setTimeout(resolve, 400));
    }
    const childrenContainer = toggleRoot?.querySelector('.note-block-children');
    const visibleText = childrenContainer?.innerText?.trim() ?? '';
    const childRowCount = childrenContainer
      ? childrenContainer.querySelectorAll('[data-note-block-row], [data-note-editor-host], [data-note-preview-text]').length
      : 0;
    return {
      ok: true,
      titleValue: input.value,
      childRowCount,
      visibleText,
    };
  }, titleNeedle).then((result) => {
    if (!result.ok) throw new Error(`toggle "${titleNeedle}" not in DOM (${result.reason})`);
    return result;
  });
}

async function createFreshDocumentWithToggleBody(page) {
  return page.evaluate(async (marker) => {
    const docRes = await fetch('/api/admin/note/documents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ title: `Toggle Zombie QA ${Date.now()}` }),
    });
    if (!docRes.ok) throw new Error(`document create ${docRes.status}`);
    const { document } = await docRes.json();
    const blockRes = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: document.id,
        type: 'toggle',
        content: { title: 'QA Toggle', body: marker, collapsed: false },
        order_index: 0,
        parent_block_id: null,
      }),
    });
    if (!blockRes.ok) throw new Error(`toggle create ${blockRes.status}`);
    const { block } = await blockRes.json();
    return { documentId: document.id, toggleId: block.id };
  }, ZOMBIE_MARKER);
}

const TOGGLE_KB_TITLE = 'KB QA Toggle';

async function createFreshDocumentWithToggleAndChild(page, { childText = '' } = {}) {
  return page.evaluate(async ({ title, text }) => {
    const docRes = await fetch('/api/admin/note/documents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ title: `Toggle KB QA ${Date.now()}` }),
    });
    if (!docRes.ok) throw new Error(`document create ${docRes.status}`);
    const { document } = await docRes.json();
    const toggleRes = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: document.id,
        type: 'toggle',
        content: { title, collapsed: false },
        order_index: 0,
        parent_block_id: null,
      }),
    });
    if (!toggleRes.ok) throw new Error(`toggle create ${toggleRes.status}`);
    const { block: toggle } = await toggleRes.json();
    const childRes = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: document.id,
        type: 'text',
        content: { text, html: text ? `<p>${text}</p>` : '<p></p>' },
        order_index: 0,
        parent_block_id: toggle.id,
      }),
    });
    if (!childRes.ok) throw new Error(`child create ${childRes.status}`);
    const { block: child } = await childRes.json();
    return { documentId: document.id, toggleId: toggle.id, childId: child.id, title };
  }, { title: TOGGLE_KB_TITLE, text: childText });
}

async function waitForBootstrapDocument(page, documentId) {
  await page.waitForFunction(async (id) => {
    const res = await fetch('/api/admin/note/bootstrap', { credentials: 'include' });
    if (!res.ok) return false;
    const json = await res.json();
    return (json.documents ?? []).some((doc) => doc.id === id);
  }, documentId, { timeout: 20000 });
}

async function expandToggleByTitleInDom(page, titleNeedle) {
  await page.evaluate(async (needle) => {
    const inputs = [...document.querySelectorAll('[data-toggle-title]')];
    const input = inputs.find((el) => (el.value || '').includes(needle));
    if (!input) throw new Error(`toggle title "${needle}" not found`);
    input.scrollIntoView({ block: 'center' });
    const toggleRoot = input.closest('.relative.overflow-visible.py-0\\.5')
      ?? input.parentElement?.parentElement;
    const button = toggleRoot?.querySelector('button[aria-label]');
    if (button?.getAttribute('aria-label') === '펼치기') {
      button.click();
      await new Promise((resolve) => setTimeout(resolve, 400));
    }
  }, titleNeedle);
}

async function focusToggleChildEditor(page) {
  await page.waitForFunction(() => {
    const container = document.querySelector('.note-block-children');
    if (!container) return false;
    return container.querySelectorAll(
      '[data-note-block-row], [data-note-preview-text], .ProseMirror, [data-note-editor-host]',
    ).length > 0;
  }, { timeout: 20000 });

  const childArea = page.locator('.note-block-children').first();
  const preview = childArea.locator('[data-note-preview-text]').first();
  if (await preview.count()) {
    await preview.click();
    await page.waitForTimeout(400);
  }
  const editor = childArea.locator('.ProseMirror').first();
  if (await editor.count()) {
    await editor.waitFor({ state: 'visible', timeout: 10000 });
    await editor.click();
  } else if (await preview.count()) {
    await preview.click();
  } else {
    const row = childArea.locator('[data-note-block-row]').first();
    await row.click({ position: { x: 48, y: 12 } });
  }
  await page.waitForTimeout(200);
  return childArea.locator('.ProseMirror').first();
}

async function assertToggleTitleFocused(page, titleNeedle) {
  await page.waitForTimeout(500);
  await page.waitForFunction((needle) => {
    const active = document.activeElement;
    if (!active || active.tagName !== 'INPUT') return false;
    if (!active.hasAttribute('data-toggle-title')) return false;
    return (active.value || '').includes(needle);
  }, titleNeedle, { timeout: 12000 });
}

async function createFreshDocumentWithTextBlock(page) {
  return page.evaluate(async () => {
    const docRes = await fetch('/api/admin/note/documents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ title: `Regression QA ${Date.now()}` }),
    });
    if (!docRes.ok) throw new Error(`document create ${docRes.status}`);
    const { document } = await docRes.json();
    const blockRes = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: document.id,
        type: 'text',
        content: { text: '삭제QA마커', html: '<p>삭제QA마커</p>' },
        order_index: 0,
        parent_block_id: null,
      }),
    });
    if (!blockRes.ok) throw new Error(`block create ${blockRes.status}`);
    const { block } = await blockRes.json();
    return { documentId: document.id, blockId: block.id };
  });
}

async function softDeleteBlock(page, blockId) {
  await page.evaluate(async (id) => {
    const res = await fetch('/api/admin/note/blocks', {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ ids: [id] }),
    });
    if (!res.ok) throw new Error(`soft delete ${res.status}`);
  }, blockId);
}

async function main() {
  const chromium = await loadPlaywrightChromium();
  const browser = await chromium.launch({ headless: true });
  let failed = 0;
  let context;
  let page;

  try {
    context = await createNoteQaContext(browser, BASE);
    page = await context.newPage();

    failed += await runCheck('공통 보드 문서 로드', async () => {
      await openDocument(page, COMMON_BOARD_ID);
      const urlId = new URL(page.url()).searchParams.get('id');
      if (urlId !== COMMON_BOARD_ID) throw new Error(`expected ${COMMON_BOARD_ID}, got ${urlId}`);
      const rows = await page.locator('[data-note-block-row]').count();
      if (rows < 1) throw new Error('no block rows');
    });

    failed += await runCheck('최지훈 업무노트 빈 껍데기 없음', async () => {
      await openDocument(page, JIHOON_NOTE_ID);
      const blocks = await fetchBlocks(page, JIHOON_NOTE_ID);
      if (blocks.length < 5) {
        throw new Error(`expected many active blocks, got ${blocks.length}`);
      }
      const rows = await page.locator('[data-note-block-row]').count();
      if (rows < 1) throw new Error('no visible block rows after load settled');
    });

    failed += await runCheck('문서 전환 시 빈 껍데기 프레임 없음', async () => {
      await openDocument(page, COMMON_BOARD_ID);
      await page.goto(
        `${BASE}/admin/note?id=${encodeURIComponent(JIHOON_NOTE_ID)}`,
        { waitUntil: 'domcontentloaded' },
      );
      const skeleton = page.getByRole('status', { name: '페이지 불러오는 중' });
      const rows = page.locator('[data-note-block-row]');
      const firstPaint = await Promise.race([
        skeleton.waitFor({ state: 'visible', timeout: 2500 }).then(() => 'skeleton'),
        rows.first().waitFor({ state: 'visible', timeout: 2500 }).then(() => 'rows'),
      ]).catch(() => 'empty');
      if (firstPaint === 'empty') {
        throw new Error('document switch showed neither skeleton nor cached rows');
      }
      await skeleton.waitFor({ state: 'detached', timeout: 45000 }).catch(() => undefined);
      await rows.first().waitFor({ state: 'visible', timeout: 45000 });
    });

    failed += await runCheck('hard refresh 후 공통 보드 블록 유지', async () => {
      await openDocument(page, COMMON_BOARD_ID);
      const before = await fetchBlocks(page, COMMON_BOARD_ID);
      if (before.length < 1) throw new Error('no blocks before reload');
      await page.reload({ waitUntil: 'domcontentloaded' });
      await page.getByRole('status', { name: '페이지 불러오는 중' }).waitFor({ state: 'detached', timeout: 45000 }).catch(() => undefined);
      await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 45000 });
      const after = await fetchBlocks(page, COMMON_BOARD_ID);
      if (after.length < before.length * 0.5) {
        throw new Error(`block count dropped after reload: ${before.length} -> ${after.length}`);
      }
    });

    failed += await runCheck('blocks/load 기본 경로에 skipReconcile 없음 (앱)', async () => {
      const usesSkip = await page.evaluate(async (docId) => {
        const res = await fetch(`/api/admin/note/blocks/load?documentId=${encodeURIComponent(docId)}`, {
          credentials: 'include',
        });
        return res.ok;
      }, COMMON_BOARD_ID);
      if (!usesSkip) throw new Error('full load failed');
    });

    failed += await runCheck('토글 DB 자식 본문 존재 (시드)', async () => {
      const body = `시드토글본문-${Date.now()}`;
      const seeded = await createFreshDocumentWithToggleAndChild(page, { childText: body });
      await openDocument(page, seeded.documentId);
      const blocks = await fetchBlocks(page, seeded.documentId);
      const toggle = blocks.find((b) => b.id === seeded.toggleId);
      const children = blocks.filter((b) => b.parent_block_id === seeded.toggleId);
      const childText = children
        .map((c) => (typeof c.content?.text === 'string' ? c.content.text : ''))
        .join(' ')
        .trim();
      if (!toggle || toggle.type !== 'toggle') {
        throw new Error(`seeded toggle missing: ${JSON.stringify({ toggle, children: children.length })}`);
      }
      if (!childText.includes(body)) {
        throw new Error(`seeded toggle child body missing: "${childText}"`);
      }
    });

    failed += await runCheck('토글 UI 펼침 후 자식 본문 표시 (시드)', async () => {
      const body = `시드토글UI-${Date.now()}`;
      const seeded = await createFreshDocumentWithToggleAndChild(page, { childText: body });
      await openDocument(page, seeded.documentId);
      // createFresh… 기본 collapsed:false 이지만 UI는 !!collapsed로 펼침 보장
      const { childRowCount, visibleText } = await expandToggleByTitleInDomAndRead(page, TOGGLE_KB_TITLE);
      if (childRowCount < 1 && !visibleText) {
        throw new Error(`toggle expanded but no child rows (visible="${visibleText}")`);
      }
      if (!visibleText.includes(body.slice(0, 8))) {
        throw new Error(`visible "${visibleText.slice(0, 80)}" does not include "${body}"`);
      }
    });

    failed += await runCheck('삭제 후 새로고침 시 블록 부활 없음', async () => {
      const { documentId, blockId } = await createFreshDocumentWithTextBlock(page);
      await softDeleteBlock(page, blockId);
      await page.reload({ waitUntil: 'domcontentloaded' });
      await page.waitForTimeout(2000);
      const blocks = await fetchBlocks(page, documentId);
      const zombie = blocks.find((b) => b.id === blockId);
      if (zombie) throw new Error(`deleted block ${blockId} still in load response`);
      const marker = blocks.some((b) => (b.content?.text ?? '').includes('삭제QA마커'));
      if (marker) throw new Error('deleted marker text still visible in another block');
    });

    failed += await runCheck('토글 자식 삭제 + idle 후 legacyBody 좀비 재생성 없음', async () => {
      const { documentId, toggleId } = await createFreshDocumentWithToggleBody(page);
      await openDocument(page, documentId);
      let blocks = await fetchBlocks(page, documentId);
      let children = blocks.filter((b) => b.parent_block_id === toggleId);
      if (children.length === 0) {
        await page.waitForTimeout(2000);
        blocks = await fetchBlocks(page, documentId);
        children = blocks.filter((b) => b.parent_block_id === toggleId);
      }
      if (children.length === 0) {
        throw new Error('toggle migration did not create child before delete test');
      }
      const childId = children[0].id;
      await softDeleteBlock(page, childId);
      await page.waitForTimeout(RECONCILE_WAIT_MS);
      await page.reload({ waitUntil: 'domcontentloaded' });
      await page.waitForTimeout(2000);
      blocks = await fetchBlocks(page, documentId);
      const zombieChild = blocks.find((b) => b.id === childId);
      if (zombieChild) throw new Error(`deleted toggle child ${childId} still in load`);
      const respawned = blocks.filter((b) => b.parent_block_id === toggleId);
      const markerInChild = respawned.some((b) => (b.content?.text ?? '').includes(ZOMBIE_MARKER));
      if (markerInChild) {
        throw new Error(`legacyBody resurrected child with marker "${ZOMBIE_MARKER}"`);
      }
      const toggle = blocks.find((b) => b.id === toggleId);
      const legacy = [
        toggle?.content?.legacyBody,
        toggle?.content?.body,
      ].filter((v) => typeof v === 'string' && v.includes(ZOMBIE_MARKER));
      if (legacy.length > 0) {
        throw new Error('toggle still archives zombie marker in content after child delete');
      }
    });

    failed += await runCheck('토글 첫 자식 빈 Backspace → 제목 포커스', async () => {
      const { documentId } = await createFreshDocumentWithToggleAndChild(page);
      await waitForBootstrapDocument(page, documentId);
      await openDocument(page, documentId);
      await page.waitForFunction(async (id) => {
        const res = await fetch(`/api/admin/note/blocks/load?documentId=${encodeURIComponent(id)}`, {
          credentials: 'include',
        });
        if (!res.ok) return false;
        const json = await res.json();
        return (json.blocks ?? []).some((b) => b.parent_block_id);
      }, documentId, { timeout: 20000 });
      await expandToggleByTitleInDom(page, TOGGLE_KB_TITLE);
      await focusToggleChildEditor(page);
      await page.keyboard.press('Backspace');
      await assertToggleTitleFocused(page, TOGGLE_KB_TITLE);
    });

    failed += await runCheck('토글 첫 자식 맨 앞 Backspace → 제목 포커스', async () => {
      const { documentId } = await createFreshDocumentWithToggleAndChild(page, { childText: 'x' });
      await waitForBootstrapDocument(page, documentId);
      await openDocument(page, documentId);
      await page.waitForFunction(async (id) => {
        const res = await fetch(`/api/admin/note/blocks/load?documentId=${encodeURIComponent(id)}`, {
          credentials: 'include',
        });
        if (!res.ok) return false;
        const json = await res.json();
        return (json.blocks ?? []).some((b) => b.parent_block_id);
      }, documentId, { timeout: 20000 });
      await expandToggleByTitleInDom(page, TOGGLE_KB_TITLE);
      const childEditor = await focusToggleChildEditor(page);
      if (await childEditor.count()) {
        await childEditor.click();
      }
      await page.keyboard.press('Home');
      await page.keyboard.press('Backspace');
      await assertToggleTitleFocused(page, TOGGLE_KB_TITLE);
    });

    failed += await runCheck('타이핑 후 idle — 본문 유지 (smoke parity)', async () => {
      const { documentId: docId } = await createFreshDocumentWithTextBlock(page);
      await page.waitForFunction(async (id) => {
        const res = await fetch('/api/admin/note/bootstrap', { credentials: 'include' });
        if (!res.ok) return false;
        const json = await res.json();
        return (json.documents ?? []).some((doc) => doc.id === id);
      }, docId, { timeout: 20000 });
      await openDocument(page, docId);
      const row = page.locator('[data-note-block-row]').first();
      await row.waitFor({ state: 'visible', timeout: 45000 });
      const preview = row.locator('[data-note-preview-text]');
      if (await preview.count()) {
        await preview.click();
      } else {
        await row.click({ position: { x: 96, y: 14 } });
      }
      await page.waitForTimeout(500);
      const editor = page.locator('[data-note-block-row]').first().locator('.ProseMirror').first();
      await editor.waitFor({ state: 'visible', timeout: 15000 });
      await editor.click();
      await page.keyboard.press('Control+A');
      await page.keyboard.type('타이핑유지QA', { delay: 10 });
      await page.locator('div.cursor-text').first().click({ position: { x: 100, y: 200 }, force: true });
      await page.waitForTimeout(800);
      await page.waitForFunction(async (id) => {
        const res = await fetch(`/api/admin/note/blocks/load?documentId=${encodeURIComponent(id)}`, {
          credentials: 'include',
        });
        if (!res.ok) return false;
        const json = await res.json();
        const blocks = (json.blocks ?? []).filter((b) => b.type === 'text').sort((a, b) => a.order_index - b.order_index);
        const text = blocks[0]?.content?.text ?? '';
        return text.includes('타이핑유지QA');
      }, docId, { timeout: 45000 });
    });

  } finally {
    try {
      const cleaned = await cleanupEphemeralQaDocumentsBestEffort(page, REGRESSION_CLEANUP_OPTIONS);
      if (cleaned.deleted > 0) {
        console.log(`Cleaned ${cleaned.deleted} ephemeral QA document(s) via ${cleaned.via}.`);
      }
      for (const cleanupError of cleaned.errors) {
        console.warn('WARN cleanup fallback:', cleanupError.message);
      }
    } catch (cleanupError) {
      console.error(
        'QA doc cleanup failed:',
        cleanupError instanceof Error ? cleanupError.message : cleanupError,
      );
      failed += 1;
    }
    if (context) await context.close().catch(() => undefined);
    await browser.close();
  }

  if (failed > 0) {
    console.error(`\n${failed} regression check(s) failed.`);
    process.exit(1);
  }
  console.log('\nAll admin note regression checks passed.');
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

import nextEnv from '@next/env';
import {
  NOTE_QA_DOCUMENTS,
  createNoteQaContext,
  loadPlaywrightChromium,
} from './note-qa/shared.mjs';
import {
  cleanupEphemeralQaDocumentsBestEffort,
  cleanupEphemeralQaDocumentsViaPage,
} from './note-qa/cleanupEphemeralDocs.mjs';

const { loadEnvConfig } = nextEnv;
loadEnvConfig(process.cwd());

/**
 * Admin Note smoke (logged-in browser).
 *
 * Usage:
 *   node scripts/admin-note-smoke-qa.mjs http://localhost:3000
 *
 * Auth (우선순위):
 *   1) SUPABASE_SERVICE_ROLE_KEY + QA admin user → magic link 세션
 *   2) SPM_QA_PASSWORD + ADMIN_NOTE_QA_ID → 로그인 폼
 */
const BASE = (process.argv[2] || 'http://localhost:3000').replace(/\/$/, '');
const QA_PASSWORD = process.env.ADMIN_NOTE_QA_PASSWORD || process.env.SPM_QA_PASSWORD || '';
const RECONCILE_WAIT_MS = 3500;
/** CI·로컬 invariant QA와 동일한 고정 문서 */
const FALLBACK_QA_DOC_ID = NOTE_QA_DOCUMENTS[0]?.id ?? '7c095438-335b-4318-a3fb-09145f01d24a';

async function createAuthenticatedContext(browser) {
  try {
    return await createNoteQaContext(browser, BASE);
  } catch (authError) {
    if (!QA_PASSWORD) throw authError;
  }

  const QA_ID = process.env.ADMIN_NOTE_QA_ID || process.env.SPM_QA_ADMIN_EMAIL || 'spm.qa.admin@spokedu.test';
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  await page.goto(`${BASE}/login?type=admin&next=${encodeURIComponent('/admin/note')}`, {
    waitUntil: 'domcontentloaded',
  });
  await page.locator('input[type="text"]').first().fill(QA_ID);
  await page.locator('input[type="password"]').first().fill(QA_PASSWORD);
  await page.locator('button[type="submit"]').click();
  await page.waitForURL(/\/admin\/note/, { timeout: 90000, waitUntil: 'domcontentloaded' });
  await page.close();
  return context;
}

function documentIdFromPage(page) {
  return new URL(page.url()).searchParams.get('id');
}

async function waitForDocumentBlocksHydrated(page, documentId) {
  await page.waitForFunction(async (expectedId) => {
    const urlId = new URL(location.href).searchParams.get('id');
    if (urlId !== expectedId) return false;
    const res = await fetch(
      `/api/admin/note/blocks/load?documentId=${encodeURIComponent(expectedId)}&skipReconcile=true`,
      { credentials: 'include' },
    );
    if (!res.ok) return false;
    const json = await res.json();
    return Array.isArray(json.blocks);
  }, documentId, { timeout: 30000 });
  await page.getByRole('status', { name: '페이지 불러오는 중' }).waitFor({ state: 'detached', timeout: 30000 }).catch(() => undefined);
  await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 30000 });
  await page.waitForTimeout(800);
}

async function openDocument(page, documentId, { requireBlocks = true } = {}) {
  await page.goto(
    `${BASE}/admin/note?id=${encodeURIComponent(documentId)}`,
    { waitUntil: 'domcontentloaded' },
  );
  await page.waitForLoadState('networkidle').catch(() => undefined);
  await page.getByRole('status', { name: '페이지 불러오는 중' }).waitFor({ state: 'detached', timeout: 30000 }).catch(() => undefined);
  await dismissDevOverlay(page);
  if (requireBlocks) {
    await waitForDocumentBlocksHydrated(page, documentId);
  }
  const currentId = documentIdFromPage(page);
  if (currentId !== documentId) {
    throw new Error(`openDocument expected ${documentId}, got ${currentId ?? 'none'}`);
  }
  await page.waitForTimeout(1500);
}

async function resolveLastPageChildDocumentId(page, parentDocumentId) {
  return page.evaluate(async (parentId) => {
    const res = await fetch(
      `/api/admin/note/blocks/load?documentId=${encodeURIComponent(parentId)}&skipReconcile=true`,
      { credentials: 'include' },
    );
    if (!res.ok) throw new Error(`blocks load failed (${res.status})`);
    const json = await res.json();
    const pageBlocks = (json.blocks ?? []).filter((block) => block.type === 'page');
    const last = pageBlocks[pageBlocks.length - 1];
    const childId = last?.content?.page_document_id;
    return typeof childId === 'string' && childId.length > 0 ? childId : null;
  }, parentDocumentId);
}

async function resolveDocumentId(page) {
  const fromUrl = documentIdFromPage(page);
  if (fromUrl) return fromUrl;

  await page.goto(
    `${BASE}/admin/note?id=${encodeURIComponent(FALLBACK_QA_DOC_ID)}`,
    { waitUntil: 'domcontentloaded' },
  );
  await page.waitForTimeout(1500);
  const afterNav = documentIdFromPage(page);
  if (afterNav) return afterNav;

  return page.evaluate(async (fallbackId) => {
    const res = await fetch('/api/admin/note/bootstrap', { credentials: 'include' });
    if (!res.ok) throw new Error(`bootstrap failed (${res.status})`);
    const json = await res.json();
    const docs = json.documents ?? [];
    const existing = docs.find((doc) => doc.id === fallbackId);
    if (existing) return existing.id;
    if (docs.length > 0) return docs[0].id;
    const createRes = await fetch('/api/admin/note/documents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ title: 'Smoke QA' }),
    });
    if (!createRes.ok) throw new Error(`document create failed (${createRes.status})`);
    const { document } = await createRes.json();
    return document.id;
  }, FALLBACK_QA_DOC_ID);
}

async function fetchBlocksInPage(page, documentId) {
  return page.evaluate(async (docId) => {
    const res = await fetch(
      `/api/admin/note/blocks/load?documentId=${encodeURIComponent(docId)}&skipReconcile=true`,
      { credentials: 'include' },
    );
    if (!res.ok) return { blocks: [], status: res.status };
    const json = await res.json();
    return { blocks: json.blocks ?? [], status: res.status };
  }, documentId);
}

async function seedTextBlockIfEmpty(page, explicitDocumentId) {
  const documentId = explicitDocumentId || documentIdFromPage(page);
  if (!documentId) throw new Error('document id missing in URL');
  const loaded = await fetchBlocksInPage(page, documentId);
  if (loaded.blocks.length > 0) return documentId;
  await page.evaluate(async (docId) => {
    const res = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: docId,
        type: 'text',
        content: { text: '', html: '' },
        order_index: 0,
        parent_block_id: null,
      }),
    });
    if (!res.ok) {
      const j = await res.json().catch(() => null);
      throw new Error(j?.error || `block seed failed (${res.status})`);
    }
  }, documentId);
  await page.goto(`${BASE}/admin/note?id=${encodeURIComponent(documentId)}`, { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(1500);
  const after = await fetchBlocksInPage(page, documentId);
  if (after.blocks.length < 1) throw new Error('failed to seed text block');
  return documentId;
}

async function clickDocumentBody(page) {
  const body = page.locator('[data-note-document-body="true"]').first();
  await body.waitFor({ state: 'visible', timeout: 15000 });
  const box = await body.boundingBox();
  if (box) {
    await page.mouse.click(box.x + Math.min(200, box.width * 0.5), box.y + Math.min(box.height - 24, 420));
  } else {
    await body.click({ force: true });
  }
  await page.waitForTimeout(1200);
}

async function ensureDocumentWithBlocks(page) {
  let documentId = await resolveDocumentId(page);
  await openDocument(page, documentId);
  documentId = await resolveDocumentId(page);
  await seedTextBlockIfEmpty(page, documentId);
  await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 30000 });
}

async function createFreshNote(page) {
  const docId = await page.evaluate(async () => {
    const docRes = await fetch('/api/admin/note/documents', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({ title: `Smoke ${Date.now()}` }),
    });
    if (!docRes.ok) {
      const j = await docRes.json().catch(() => null);
      throw new Error(j?.error || `document create failed (${docRes.status})`);
    }
    const { document } = await docRes.json();
    const blockRes = await fetch('/api/admin/note/blocks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        documentId: document.id,
        type: 'text',
        content: { text: '', html: '' },
        order_index: 0,
        parent_block_id: null,
      }),
    });
    if (!blockRes.ok) {
      const j = await blockRes.json().catch(() => null);
      throw new Error(j?.error || `block seed failed (${blockRes.status})`);
    }
    return document.id;
  });
  await openDocument(page, docId);
  await seedTextBlockIfEmpty(page, docId);
  await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 30000 });
  return docId;
}

async function seedSiblingBulletBlocks(page) {
  const documentId = documentIdFromPage(page);
  if (!documentId) throw new Error('document id missing in URL');
  await page.evaluate(async (docId) => {
    const create = async (orderIndex) => {
      const res = await fetch('/api/admin/note/blocks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          documentId: docId,
          type: 'bulletList',
          content: { text: '', number: 1 },
          order_index: orderIndex,
          parent_block_id: null,
        }),
      });
      if (!res.ok) throw new Error(`seed bullet failed (${res.status})`);
    };
    await create(0);
    await create(1);
  }, documentId);
  await page.goto(`${BASE}/admin/note?id=${encodeURIComponent(documentId)}`, { waitUntil: 'domcontentloaded' });
  await page.getByRole('status', { name: '페이지 불러오는 중' }).waitFor({ state: 'detached', timeout: 30000 }).catch(() => undefined);
  await page.waitForTimeout(1500);
  await page.locator('[data-note-block-row]').first().waitFor({ state: 'visible', timeout: 30000 });
  const count = await page.locator('[data-note-block-row][data-list-sibling="true"]').count();
  if (count < 2) throw new Error(`expected 2 bullet rows, got ${count}`);
}

async function focusBulletBlockAt(page, index) {
  const row = page.locator('[data-note-block-row][data-list-sibling="true"]').nth(index);
  await row.scrollIntoViewIfNeeded();
  const listHost = row.locator('[data-note-list-text]').first();
  await listHost.click({ position: { x: 40, y: 10 } });
  await page.waitForTimeout(500);
  const editor = row.locator('[data-note-list-text] .ProseMirror').first();
  await editor.waitFor({ state: 'visible', timeout: 15000 });
  await editor.click();
  return editor;
}

async function focusBlockAt(page, index) {
  const row = page.locator('[data-note-block-row]').nth(index);
  await row.scrollIntoViewIfNeeded();
  // 활성 TipTap이면 preview가 숨겨져 있다 — visible 대기 대신 force/ProseMirror 직접 클릭
  const existingProse = row.locator('.ProseMirror').first();
  if (await existingProse.count()) {
    await existingProse.click({ force: true });
    await page.waitForTimeout(300);
    return existingProse;
  }
  const preview = row.locator('[data-note-preview-text]').first();
  if (await preview.count()) {
    await preview.click({ force: true });
  } else {
    await row.click({ position: { x: 96, y: 14 }, force: true });
  }
  await page.waitForTimeout(500);
  const inRow = row.locator('.ProseMirror').first();
  if (await inRow.count()) {
    await inRow.click({ force: true });
    return inRow;
  }
  await row.locator('[data-note-editor-host]').first().click({ force: true });
  const editor = page.locator('.ProseMirror:visible').last();
  await editor.waitFor({ state: 'visible', timeout: 15000 });
  await editor.click({ force: true });
  return editor;
}

async function focusLastEditor(page) {
  const editable = page.locator(
    '[data-note-block-row] [data-note-editor-host], [data-note-block-row] [data-note-list-text]',
  );
  const count = await editable.count();
  if (count > 0) {
    const host = editable.last();
    await host.scrollIntoViewIfNeeded();
    await host.click({ position: { x: 40, y: 10 } });
    await page.waitForTimeout(400);
    const editor = host.locator('.ProseMirror').first();
    if (await editor.count()) {
      await editor.click();
      return editor;
    }
  }
  const rowCount = await page.locator('[data-note-block-row]').count();
  if (rowCount < 1) throw new Error('no block rows');
  return focusBlockAt(page, rowCount - 1);
}

async function clickEditorWhitespace(page) {
